(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Аанг","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Лавочник! Аппа полностью отдохнул!"},{"a":"atlab_aang","t":"Значит... Видимо, пришло время прощаться..."},{"a":"atlab_sokka","t":"Эй, не унывай! Мы можем вернуться в любое время!"},{"a":"atlab_aang","t":"Точно! Ты помнишь дорогу, Сокка?"},{"a":"atlab_sokka","t":"Э-э... Я не обратил внимания..."},{"a":"atlab_sokka","t":"Л-ладно! У нас есть важные аватарские дела, к которым мы должны вернуться!"},{"a":"atlab_sokka","t":"Эй, Момо! Мы уходим!"},{"a":"atlab_aang","t":"Момо! Момо?.."},{"a":"atlab_aang","t":"Тебе здесь нравится, да? Ладно, хорошо."},{"a":"atlab_aang","t":"Лавочник, ты не против присмотреть за Момо некоторое время?"},{"a":"atlab_aang","t":"Я вернусь за тобой позже, Момо. Обещаю!"},{"a":"atlab_aang","t":"Пойдем, Сокка. Спасибо за все, лавочник!"},{"a":"atlab_sokka","t":"Пока!"},{"a":"atlab_aang","t":"Давай, Аппа! Ип-ип!"}]},{"id":"atlab_aang_01","i":1,"title":"Судьбоносный поворот не туда","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"inn","t":"Прости, малыш, я не все понял. Ты не против повторить свою историю с самого начала?"},{"a":"atlab_aang","t":"Простите! Позвольте начать сначала!"},{"a":"atlab_aang","t":"Я Аватар Аанг."},{"a":"atlab_aang","t":"Мы с друзьями путешествовали на моем летающем зубре..."},{"a":"atlab_aang","t":"Во время полета мы, должно быть, свернули не туда, потому что оказались здесь!"},{"a":"inn","t":"Тот огромный бык снаружи? Он летает?"},{"a":"atlab_aang","t":"Да! Его зовут Аппа. Он дружелюбный!"},{"a":"inn","t":"Выглядит измотанным. За вами кто-то гонится, да?"},{"a":"atlab_aang","t":"О, э-э..."},{"a":"inn","t":"Эй, не волнуйся. Под моей крышей вас никто не обидит. Оскар обещает."},{"a":"inn","t":"Вот что, ребята, не хотели бы вы остаться здесь на постой бесплатно?"},{"a":"atlab_aang","t":"Бесплатно? Правда?!"},{"a":"inn","t":"Начнем с того, что ваши странные деньги, похоже, здесь ничего не стоят."},{"a":"inn","t":"Но не могу же я позволить кучке детей спать на улице, верно?"},{"a":"atlab_aang","t":"С-спасибо, господин Оскар!"},{"a":"inn","t":"Ты выглядишь довольно способным. Как насчет в обмен на постой помочь моему другу лавочнику?"},{"a":"atlab_aang","t":"Конечно! Большое спасибо!"}]},{"id":"atlab_aang_02","i":2,"title":"Управление огнем?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"inn","t":"Привет, Лилу! Познакомься с моим новым приятелем!"},{"a":"lilu","t":"Привет! Никогда не видела таких татуировок, как у тебя..."},{"a":"atlab_aang","t":"Я Аанг! Я никогда не видел такой шляпы, как у тебя!"},{"a":"inn","t":"Давай, Аанг, покажи ей свой трюк!"},{"a":"atlab_aang","t":"Вот... этот?"},{"a":"lilu","t":"Как ты это сделал? Я не почувствовала никакой магии!"},{"a":"atlab_aang","t":"Управление воздухом! Я также могу управлять землей и водой!"},{"a":"lilu","t":"Невероятно! Погоди, дай записать..."},{"a":"lilu","t":"Возможно, это ци? Никогда не видела, чтобы кто-то проделывал такое раньше..."},{"a":"atlab_aang","t":"Верно! Не каждый может это сделать, нужно родиться со способностью и научиться ею владеть!"},{"a":"lilu","t":"Ты сказал, что можешь управлять воздухом, землей и водой... а как насчет огня?"},{"a":"atlab_aang","t":"Э-э... Я... Я еще не освоил управление огнем..."},{"a":"atlab_aang","t":"У меня были проблемы с поиском учителя по управлению огнем..."},{"a":"lilu","t":"Неужели? А я немного знаю магию огня!"},{"a":"lilu","t":"Это не совсем то же самое, но, возможно, тебе будет приятно посмотреть, как она работает!"},{"a":"atlab_aang","t":"А... конечно. Спасибо, Лилу."}]},{"id":"atlab_aang_03","i":3,"title":"Повелитель стихий","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"elderowen","t":"Аанг, мой мальчик. Как тебе нравится городская жизнь?"},{"a":"atlab_aang","t":"Старейшина Оуэн! Все здорово! Спасибо за гостеприимство."},{"a":"elderowen","t":"Всегда пожалуйста. Но скажи мне, мой мальчик, где твои родители?"},{"a":"atlab_aang","t":"А... У меня больше нет... родителей."},{"a":"atlab_aang","t":"Моя семья... все Воздушные кочевники были убиты Народом Огня."},{"a":"atlab_aang","t":"Остался только я один."},{"a":"elderowen","t":"Батюшки! Мои соболезнования, бедное дитя..."},{"a":"elderowen","t":"Если тебе некуда возвращаться, может, поселишься со своими друзьями здесь?"},{"a":"elderowen","t":"Уверен, что в городе будут рады, если вы останетесь. Вы уже довольно популярны!"},{"a":"atlab_aang","t":"Спасибо за щедрое предложение, старейшина... но я не могу его принять."},{"a":"atlab_aang","t":"Прямо сейчас Хозяин Огня Озай уже планирует свой следующий шаг."},{"a":"atlab_aang","t":"Когда комета Созина вновь озарит небо, Народ Огня завоюет мой мир..."},{"a":"atlab_aang","t":"Царство Земли... Племя Воды... Их постигнет та же участь, что и Воздушных кочевников."},{"a":"atlab_aang","t":"Я, как Аватар, единственный, кто может его остановить! Но я не готов."},{"a":"elderowen","t":"Какое ужасное бремя приходится нести ребенку..."},{"a":"elderowen","t":"Как бы то ни было, знай, что наш город полностью вас поддерживает."},{"a":"atlab_aang","t":"Спасибо, старейшина. Вы все уже так много сделали для нас!"},{"a":"atlab_aang","t":"Мы обязательно навестим вас, когда все закончится!"}]},{"id":"atlab_aang_04","i":4,"title":"Знамение Созина","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"mana","t":"Аватар. Наши пути наконец пересеклись."},{"a":"atlab_aang","t":"Кто ты? Откуда ты меня знаешь?"},{"a":"mana","t":"Присутствие Аватара сияет подобно маяку для третьего глаза."},{"a":"atlab_aang","t":"А, гадание... Я пас!"},{"a":"mana","t":"Ты, кого много, но кто еще не совсем цел..."},{"a":"mana","t":"Тебя ждет жестокая битва с Владыкой Огня."},{"a":"atlab_aang","t":"Хозяин Огня Озай... Ты знаешь о нем?"},{"a":"mana","t":"Под взглядом кометы земля будет разорвана на части, а поля — сожжены в пепел!"},{"a":"atlab_aang","t":"Я это знаю! Но что мне делать?"},{"a":"mana","t":"Течение судьбы нельзя нарушить."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"Но смелые могут потянуть за ниточки и сбить его с пути."},{"a":"mana","t":"Ключевое значение могут обрести маловероятный союзник и хрупкий союз."},{"a":"atlab_aang","t":"Спасибо, гадалка... Я подумаю об этом."},{"a":"mana","t":"..."},{"a":"mana","t":"Будь храбрым, Аватар. Оставайся верным себе, и ты победишь."}]}]},{"id":"argon","name":"Аргон","chapters":[{"id":"argon_01","i":1,"title":"Тень короля","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"...И тогда я поразил гиблина своим мечом! Раз — и все!"},{"a":"elderowen","t":"Хо-хо! Вот так история, Аргон!"},{"a":"elderowen","t":"Ах, пыл молодости..."},{"a":"elderowen","t":"Признаюсь, очень мило с твоей стороны сопровождать меня, старика, на утренней прогулке."},{"a":"argon","t":"Не стоит благодарности! Раз уж я хочу стать рыцарем, то должен помогать нуждающимся!"},{"a":"elderowen","t":"Как твой отец, да? Уверен, мальчик мой, из тебя выйдет прекрасный рыцарь."},{"a":"elderowen","t":"Возможно, даже попадешь в стражу самого короля!"},{"a":"elderowen","t":"А вот и он по рынку бродит, легок на помине! Вот возьми и спроси его!"},{"a":"argon","t":"ВАШЕ ВЕЛИЧЕСТВО! Я хочу предложить вам свои услуги в качестве рыцаря!"},{"a":"king","t":"Э-это еще что такое?! Сиа, разберись с этим простолюдином!"},{"a":"sia","t":"Конечно, мой король."},{"a":"sia","t":"Ну что, молодой человек? В чем дело?"},{"a":"argon","t":"Ух ты! Я, э-э..."},{"a":"argon","t":"Я рыцарь! Хочу стать Аргоном!"},{"a":"argon","t":"Ой, погодите..."},{"a":"sia","t":"А ты смелый парень!"},{"a":"sia","t":"Если ты так полон решимости, приходи ко мне на следующей неделе во двор замка."},{"a":"sia","t":"А до этого усердно тренируйся! Я не потерплю лоботряса среди рыцарей короля..."}]},{"id":"argon_02","i":2,"title":"Череда тренировок","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Аргон, что ты здесь делаешь?"},{"a":"argon","t":"Усердно тренируюсь! У меня наконец появился шанс стать рыцарем короля!"},{"a":"lilu","t":"Короля? ...Или Сиа, его таинственной советницы?"},{"a":"argon","t":"Ее так зовут? И имя тоже красивое!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Ох! Нет! Имеет значение только король!"},{"a":"argon","t":"Я должен стать рыцарем! Остальное неважно!"},{"a":"lilu","t":"Точно... Дай-ка я исцелю тебе раны."},{"a":"argon","t":"Спасибо. Ой! Жжется как-то твое заклинание!"}]},{"id":"argon_03","i":3,"title":"Две стороны монеты","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Так-так! Сиа может появиться в любой момент!"},{"a":"argon","t":"Мое обучение окупилось, я готов!"},{"a":"argon","t":"Но по-прежнему очень нервничаю..."},{"a":"argon","t":"Ой! Привет! Да, ты, в кустах!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Тоже хочешь стать рыцарем?"},{"a":"argon","t":"Сиа скоро будет здесь! Не нужно прятаться, она очень милая!"},{"a":"yami","t":"Сиа!.."},{"a":"yami","t":"Мне нужно идти. Прощай."},{"a":"argon","t":"П-постой!"},{"a":"argon","t":"Ого! Дымовая шашка?!"},{"a":"argon","t":"Какая странная девушка..."},{"a":"sia","t":"Молодой человек, вы с кем разговариваете?"},{"a":"argon","t":"А, Сиа! Да так, мимо кто-то проходил! Не обращайте внимания!"},{"a":"sia","t":"...Ясно. Что же, похоже, твоя решимость не дрогнула."},{"a":"sia","t":"Готов ли ты рисковать жизнью в качестве рыцаря короля?"},{"a":"argon","t":"А как же! Т-то есть конечно! Отец будет гордиться мной!"},{"a":"sia","t":"Хорошо. И вот тебе первое задание. Грядет одно важное событие..."}]},{"id":"argon_04","i":4,"title":"С пустыми руками","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Ты шутишь, что ли?"},{"a":"sia","t":"Ты загнал убийцу в угол... но не смог ее остановить."},{"a":"sia","t":"Более того, ты говоришь, что ОТПУСТИЛ ЕЕ, решив, что она хороший человек?!"},{"a":"argon","t":"..."},{"a":"sia","t":"Что за вздор?"},{"a":"sia","t":"Ты ведь понимаешь, что она пыталась убить нашего короля — человека, которого ты поклялся защищать?"},{"a":"sia","t":"Такой инцидент ставит под угрозу гораздо большее, чем твой слабый ум способен понять."},{"a":"sia","t":"Ух... Полагаю, последнее слово об увольнении рыцаря должен сказать король..."},{"a":"sia","t":"...Но не жди, что я буду высоко о тебе отзываться. Свободен."},{"a":"argon","t":"..."},{"a":"argon","t":"Ой-ой..."},{"a":"argon","t":"Прости, папа."}]},{"id":"argon_a","i":4,"title":"Башня титанов","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"elderowen","t":"Башня титанов?"},{"a":"lilu","t":"Пожалуйста, расскажите нам о ней!"},{"a":"argon","t":"Я слышал, как какие-то герои шептались о ней, но никто никогда ее не видел..."},{"a":"elderowen","t":"Да, Башня титанов — это мистическое место. Никто не знает, существует ли она на самом деле."},{"a":"elderowen","t":"Рассказывают, что она появляется из ниоткуда, и самые могучие герои проходят испытание, поднимаясь по ней этаж за этажом..."},{"a":"elderowen","t":"...пока башня внезапно не исчезает, стирая воспоминания у любого, кто мог ее видеть."},{"a":"argon","t":"С-стирая воспоминания?!"},{"a":"lilu","t":"Странно... А откуда тогда взялась бы легенда?"},{"a":"argon","t":"Точно! Кто-то же должен был помнить!"},{"a":"elderowen","t":"Говорят, что тех, кто проходит испытание титана, башня считает достойными."},{"a":"elderowen","t":"Эти герои возвращаются... изменившись после приобретенного опыта и сохранив воспоминания."},{"a":"elderowen","t":"Точнее, какая-то их часть остается в башне, а какая-то часть башни остается с ними."},{"a":"elderowen","t":"Хватит на сегодня историй. Спасибо, что послушали стариковские сказки."},{"a":"lilu","t":"Ух ты! Интересно, существует ли она на самом деле?"},{"a":"argon","t":"Ага! Я бы с удовольствием исследовал такое подземелье!"},{"a":"lilu","t":"Но вот что странно... Откуда старейшина Оуэн обо всем этом знает?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Странствующий рыцарь","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Ох..."},{"a":"steel","t":"Да это же Аргон! Как дела?"},{"a":"argon","t":"О, привет, Бром... Для меня работа есть?"},{"a":"steel","t":"Сегодня ничего, господин рыцарь! Чего голову повесил?"},{"a":"argon","t":"Я теперь просто Аргон. Я... потерял свое звание."},{"a":"steel","t":"Ой, какая неприятность..."},{"a":"steel","t":"«Что бы ни случилось, нужно продолжать мыслить позитивно! Ты справишься!»"},{"a":"steel","t":"Я уверен, что удача к тебе совсем скоро вернется!"},{"a":"argon","t":"Верно... Спасибо, Бром."},{"a":"argon","t":"Я... пока что поброжу по городской площади."},{"a":"argon","t":"Ох..."}]},{"id":"argon_b","i":5,"title":"Мы титаны?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"lilu","t":"Доброе утро... Аргон."},{"a":"argon","t":"(Зевает) Доброе..."},{"a":"lilu","t":"У тебя такие же ощущения, да?"},{"a":"argon","t":"Ага, я измотан! Как будто участвовал в приключениях всю ночь!"},{"a":"lilu","t":"Смотри, и щит у тебя весь побитый!"},{"a":"argon","t":"Что? Ты права! Я мог бы поклясться, что еще вчера он был начищен до блеска..."},{"a":"lilu","t":"Аргон... Как ты думаешь..."},{"a":"polonia","t":"Эй! Кто-нибудь из вас, сухопутников, хочет купить <c1>поножи Джаггернаута</c1>?"},{"a":"lilu","t":"Нет... особенно 20 штук! Ты где их достала?!"},{"a":"polonia","t":"Ха! Забавно, что спрашиваешь. Понятия не имею."},{"a":"polonia","t":"Похоже, я собираю добычу во сне. Видать, пиратской душе не спится, ар-р."},{"a":"lilu","t":"Вот и странная пиратка туда же..."},{"a":"lilu","t":"Мы что, все решили пройти испытание башни, а потом нам воспоминания стерли?.."},{"a":"argon","t":"Значит, мы не были достаточно сильны..."},{"a":"argon","t":"Буду усердно тренироваться для следующего раза! Еще посмотрим!"}]},{"id":"argon_06","i":6,"title":"Второй шанс","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Значит, ваша убийца была в руках у этого... «рыцаря»..."},{"a":"sia","t":"...Но он решил ее отпустить, считая, что она хороший человек!"},{"a":"king","t":"Замечательная история! Этот новый рыцарь, похоже, многообещающий парень!"},{"a":"sia","t":"При всем уважении, мой король..."},{"a":"sia","t":"Этот человек не стал останавливать вашу убийцу, руководствуясь лишь интуицией."},{"a":"king","t":"Отличительная черта <c1>паладина</c1>, разве нет?"},{"a":"sia","t":"Простите?"},{"a":"king","t":"Держать заклятого врага в руках, но видеть происходящее не только как раздор и конфликт..."},{"a":"king","t":"...А потом отпустить его, поскольку настолько уверен в его искуплении, что готов рискнуть собственным званием."},{"a":"king","t":"Потрясающий поступок, исполненный храбрости и великодушия!"},{"a":"sia","t":"Признаться... в таком свете я это не рассматривала, мой король."},{"a":"sia","t":"Но в королевстве уже десятки лет не было никого, кто мечтал бы стать паладином..."},{"a":"sia","t":"Мне созвать совет рыцарей для обсуждения этого вопроса?"},{"a":"king","t":"Чепуха! Я сам улажу все формальности."},{"a":"sia","t":"Как пожелаете, мой король. Я немедленно приготовлю эскорт."},{"a":"king","t":"В этом нет нужды. Я буду осторожен, как мышь!"}]},{"id":"argon_07","i":7,"title":"Неприметный король","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"king","t":"В сторону, крестьяне! Среди вас идет самый обычный работяга!"},{"a":"tavern","t":"А, король Рейнгольд! Давненько не виделись. Открыть бочку амброзии?"},{"a":"king","t":"Тс-с-с! Я сегодня под прикрытием! Не обращай на меня внимания!"},{"a":"tavern","t":"Да, конечно! Как глупо с моей стороны!"},{"a":"king","t":"Эй, ты! Который прячется за прилавком!"},{"a":"argon","t":"А? Э-э, простите, ваше величество. Я уйду с дороги..."},{"a":"king","t":"Чепуха! Будущий паладин более чем достоин сидеть рядом с моей сиятельной особой!"},{"a":"argon","t":"Сидеть рядом с... Паладин?!"},{"a":"king","t":"Именно! В своей бесконечной мудрости я ощутил в тебе большой потенциал!"},{"a":"king","t":"Несмотря на твои... необычные методы, сердце твое истинно, а чувство справедливости... восхитительно!"},{"a":"king","t":"В связи с этим королевство считает, что ты годишься для прохождения испытания паладина!"},{"a":"argon","t":"Испытания паладина... Ух ты!"},{"a":"argon","t":"Я все про них знаю! Каждое из них уникально, а его исход зависит от самого паладина..."},{"a":"argon","t":"Это должна быть опасная задача, например убить дракона... или уничтожить опасный артефакт..."},{"a":"king","t":"Верно! Подойдет любое достаточно смелое и бескорыстное деяние, совершенное во благо королевства!"},{"a":"argon","t":"Понимаю! Спасибо, ваше величество! Вы не пожалеете!"},{"a":"king","t":"Нет, конечно, я же всегда прав!"},{"a":"king","t":"...А теперь, раз я уже под прикрытием..."},{"a":"king","t":"Эй, ты! Старик! Научи меня играть в карты!"},{"a":"master","t":"В карты? Старик Теодор играет только с высокими ставками..."}]},{"id":"argon_08","i":8,"title":"Пламя снова разгорелось","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Аргон! Что за спешка?"},{"a":"argon","t":"Лилу, я буду паладином!"},{"a":"lilu","t":"Паладином! П-поразительно, Аргон! Но как?.."},{"a":"argon","t":"Король велел мне пройти испытание! Это единственный способ действительно стать достойным звания паладина."},{"a":"lilu","t":"Испытание... А ты знаешь, в чем оно состоит?"},{"a":"argon","t":"..."},{"a":"argon","t":"Ой, нет! Понятия не имею!"},{"a":"argon","t":"Это должно быть что-то эпичное и славное."},{"a":"lilu","t":"Аргон, но ты же такой славный! Повсюду побеждаешь монстров..."},{"a":"argon","t":"Конечно, но это должно быть что-то большее..."},{"a":"argon","t":"Говорят, на пике Мрачный Шпиль водятся пернатые демоны. Может быть, этого хватит..."},{"a":"lilu","t":"Что бы это ни было, я уверена, ты справишься!"},{"a":"argon","t":"Спасибо, Лилу... Даже когда я перестал быть рыцарем, ты по-прежнему в меня верила..."},{"a":"lilu","t":"Ой! Д-да это пустяки!"},{"a":"lilu","t":"В любом случае тебе в приключении понадобится помощь! Я приготовлю для тебя несколько исцеляющих свитков!"},{"a":"argon","t":"Здорово! За дело!"}]},{"id":"argon_09","i":9,"title":"Столкновение на Мрачном Шпиле (Аргон)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Ух... что за отстойное место!"},{"a":"argon","t":"Столько лезу вверх и ни одной гарпии не вижу... Даже попал в засаду убийц!"},{"a":"argon","t":"Они были похожи на ту девушку-ниндзя, правда?"},{"a":"argon","t":"Хорошо, что Лилу дала мне эти исцеляющие свитки, фух!"},{"a":"argon","t":"Думаю, здесь я отдохну."},{"a":"argon","t":"А?.."},{"a":"yami","t":"Опять ты."},{"a":"argon","t":"У-убийца короля!"},{"a":"argon","t":"Должно быть, это судьба. Награда даже получше, чем гарпия!"},{"a":"yami","t":"Ну же, давай. Я убью тебя на месте."}]},{"id":"argon_10a","i":10,"title":"Триумфальное возвращение","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Король Рейнгольд! Приключение завершено!"},{"a":"king","t":"Чудесно! Какого мерзкого зверя ты убил?"},{"a":"argon","t":"Э-э... как раз об этом."},{"a":"yami","t":"Привет."},{"a":"king","t":"Э-э-это еще что такое?!"},{"a":"sia","t":"Стража! Арестуйте их обоих!"},{"a":"argon","t":"Ой! Подождите! Она начала жизнь с чистого листа!"},{"a":"king","t":"Н-неужели?"},{"a":"yami","t":"Я пришла... извиниться."},{"a":"sia","t":"Мой король, вы, конечно, не поверите..."},{"a":"argon","t":"Я могу поручиться за нее! Честью рыцаря!"},{"a":"king","t":"Хорошо! Я выслушаю ее мольбу!"},{"a":"sia","t":"Уф... Этого я и боялась."},{"a":"sia","t":"Стража! Приведите подкрепление и следите за каждым ее шагом!"},{"a":"sia","t":"Аргон, пожалуйста, подожди снаружи, пока мы поговорим с этой... непрошеной гостьей."},{"a":"argon","t":"Сию секунду!"},{"a":"argon","t":"(Неужели я совершил огромную ошибку?..)"}]},{"id":"argon_10b","i":11,"title":"Искупитель","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Ух... Сегодня мне только этой головной боли не хватало."},{"a":"argon","t":"Леди Сиа! Как все прошло?"},{"a":"sia","t":"Вопреки всему, король Рейнгольд готов простить свою несостоявшуюся убийцу."},{"a":"sia","t":"Я не столь доверчива, но она поделилась ценной информацией о своем азумском ордене."},{"a":"argon","t":"З-значит..."},{"a":"sia","t":"Да, мы примем ее капитуляцию и извинения."},{"a":"sia","t":"Сейчас она под наблюдением лекарей из-за голода, но должна полностью поправиться."},{"a":"sia","t":"Что касается тебя, паладин Аргон..."},{"a":"argon","t":"П-паладин!"},{"a":"sia","t":"Да, устранить угрозу — это уже нечто, но способствовать искуплению заклятого врага королевства..."},{"a":"sia","t":"Похоже, король Рейнгольд был прав насчет тебя."},{"a":"sia","t":"А теперь иди и празднуй, паладин. Я уверена, что совсем скоро ты будешь сильно занят!"},{"a":"argon","t":"Да, я пойду! Благодарю!"},{"a":"argon","t":"Папа... Надеюсь, ты гордишься мной."}]},{"id":"argon_epilogue","i":12,"title":"Эпилог","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"П-паладин?! У тебя получилось, Аргон!"},{"a":"argon","t":"На мгновение я подумал, что все испортил..."},{"a":"argon","t":"Но папа был прав. Мне нужно лишь следовать за своим сердцем!"},{"a":"lilu","t":"Ах... но значит ли это, что тебя отправят в заморскую кампанию?"},{"a":"argon","t":"Пока нет. Леди Сиа надеется, что я смогу научить героев становиться паладинами."},{"a":"lilu","t":"Ах! Какое облегчение! Хотя мне трудно представить тебя в роли учителя..."},{"a":"lilu","t":"Разве ты не будешь занят сверхважными паладинскими заданиями?"},{"a":"argon","t":"Я приложу все старания! Королевство рассчитывает на меня!"},{"a":"tavern","t":"Привет, благородный паладин!"},{"a":"tavern","t":"Бром сказал, что ему нужны еще рукавицы плавильщика!"},{"a":"argon","t":"Да! Сейчас!"},{"a":"lilu","t":"Некоторые вещи никогда не меняются, да?"},{"a":"tavern","t":"Не наш Аргон, это уж точно."}]},{"id":"argon_c","i":13,"title":"Увековечено в камне","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Зелье не сработало, да?"},{"a":"lilu","t":"Ох... Мы так старались..."},{"a":"lilu","t":"Прости, Аргон. У меня не вышло... Надеюсь, тебе не очень дискомфортно."},{"a":"elderowen","t":"Гм-м... плохие вести."},{"a":"lilu","t":"У нас есть еще варианты, однако..."},{"a":"lilu","t":"Как же без него тяжко."},{"a":"elderowen","t":"Город без него будто опустел, так ведь?"},{"a":"lilu","t":"Все равно что сидеть на празднике, где никого не знаешь."},{"a":"lilu","t":"Хождение туда-сюда его не вернет. Я вернусь к этому вопросу."},{"a":"lilu","t":"Может, стоит попросить Донована о помощи."},{"a":"lilu","t":"Это нам обойдется в копеечку, но и пусть!"},{"a":"lilu","t":"Ты вряд ли сдвинешься с места, но... жди нас здесь! Мы спасем тебя!"},{"a":"argon_stone","t":"..."}]}]},{"id":"bjorn","name":"Бьорн","chapters":[{"id":"bjorn_01","i":1,"title":"Папа дома","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"bjorn","t":"Привет, детишки! Папа дома!"},{"a":"steel","t":"Папа!"},{"a":"wood","t":"...Папа."},{"a":"bjorn","t":"Что за кислый вид, Горза?"},{"a":"wood","t":"Тебя не было несколько месяцев!"},{"a":"bjorn","t":"Такова жизнь охотника! На природе, вдали от дома."},{"a":"wood","t":"Пф-ф. Все равно не помешало бы заглядывать почаще."},{"a":"bjorn","t":"Хотелось бы, но вулкан Пепельного озера не дает сидеть без дела!"},{"a":"wood","t":"Вулкан? Ты вроде говорил, что исследуешь пик Мрачный Шпиль..."},{"a":"bjorn","t":"...Я так говорил?"},{"a":"bjorn","t":"Наверное, все перепутал! Ха-ха!"},{"a":"bjorn","t":"В общем, я вам тут привез подарки! Подходите, смотрите!"},{"a":"steel","t":"О! Надеюсь, там есть Плюшевый крушитель!"}]},{"id":"bjorn_a","i":1,"title":"Лучший друг Бамхам","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"bjorn","t":"Детишки, вы не могли бы немного присмотреть за Бамхамом?"},{"a":"wood","t":"За этим мерзком кабаном? И не мечтай. Забирай его с собой."},{"a":"steel","t":"Не обижайся, папа, но он какой-то... чокнутый?"},{"a":"bjorn","t":"Ой, не говори так! Это милейшее создание!"},{"a":"wood","t":"Папа, он впадает в смертельную ярость всякий раз, как ты оставляешь его нам."},{"a":"bjorn","t":"В тот раз все произошло случайно. Он просто немного переволновался."},{"a":"wood","t":"А в остальные разы?"},{"a":"bjorn","t":"Тоже... случайно. Малыш Бамхам и мухи не обидит!"},{"a":"wood","t":"Еще как обидит, и ему это точно понравится."},{"a":"wood","t":"Послушай, папа, тебе лучше брать его с собой, когда отправляешься в город."},{"a":"steel","t":"...Ради безопасности всех."},{"a":"bjorn","t":"Хорошо, хорошо. Понял. Все в порядке, Бамхам, я люблю тебя."},{"a":"bjorn","t":"Ой-ой-ой! Бамхам, тише!"}]},{"id":"bjorn_02","i":2,"title":"Бьорн идет за продуктами","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"bjorn","t":"Спасибо всем за теплый прием! Так приятно быть дома!"},{"a":"elderowen","t":"Мы облегченно вздохнули, когда ты благополучно вернулся. Тебя не было несколько месяцев, и мы опасались худшего..."},{"a":"bjorn","t":"Простите, простите! Уж такова жизнь охотника! Ха-ха!"},{"a":"oils","t":"Знаем мы тебя. Ты, должно быть, уже думаешь о следующем походе!"},{"a":"bjorn","t":"Ха-ха! Подловили вы меня! Мы отправляемся уже завтра на рассвете!"},{"a":"oils","t":"Бьорн, ты не меняешься. Я присмотрю за Бромом и Горзой, пока тебя не будет."},{"a":"oils","t":"...Если тебе по пути, ты не против собрать для меня несколько светящихся грибов?"},{"a":"bjorn","t":"Конечно, не против! Вообще не проблема!"},{"a":"elderowen","t":"Ох... у меня в последнее время спина пошаливает. Если бы ты мог найти немного ледяного жемчуга..."},{"a":"bjorn","t":"Небольшое отступление по пути. Поищу, старейшина."},{"a":"engineer","t":"О! Бьорн! Мне нужно немного чешуи ржавого змея для моего следующего эксперимента, если ты поможешь!"},{"a":"bjorn","t":"Конечно, конечно. Принято к сведению!"},{"a":"bjorn","t":"Фу-х... Думаю, нам лучше прихватить побольше мешков, Бамхам!"}]},{"id":"bjorn_03","i":3,"title":"Озолотиться на мусоре","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"bjorn","t":"Хм... Твой нос учуял то же, что и я, Бамхам?"},{"a":"bjorn","t":"Правильно, металл. Скорее всего, мусор. Давай, Бам, найди и принеси!"},{"a":"bjorn","t":"Молодчина, дай-ка я посмотрю..."},{"a":"bjorn","t":"Хм. Странное устройство. Не думаю, что его оставили здесь случайно..."},{"a":"bjorn","t":"Спорим, что если я немного подергаю за вот эту ручку..."},{"a":"bjorn","t":"Хм... Да, именно так, как я и предполагал."},{"a":"bjorn","t":"...Сломалось. Похоже, мы не так уж много узнали, да? Ха-ха!"},{"a":"bjorn","t":"Но, думаю, у нас есть зацепка. Мы тут уже несколько месяцев рыщем, а в прошлый раз этой штуки здесь не было."},{"a":"bjorn","t":"Лучше спросить у профессионала. Ты же знаешь, что я не разбираюсь в технике!"}]},{"id":"bjorn_04","i":4,"title":"Неизвестный маячок","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"engineer","t":"Какая странная вещь! Никогда не видела ничего подобного."},{"a":"engineer","t":"Похоже, здесь сочетаются магия и наука, и это своего рода... маячок? Радар?"},{"a":"engineer","t":"Говоришь, он был сломан, когда вы его нашли?"},{"a":"bjorn","t":"Да. Вот ведь невезение, правда? Ха-ха!"},{"a":"engineer","t":"Обидно. Больше ничего не могу сказать, кроме того, что эта штука определенно отправляет какую-то информацию."},{"a":"engineer","t":"Знаешь что, если дашь мне минутку, я сделаю для тебя устройство, которое поможет найти больше таких... «магических маячков»."},{"a":"bjorn","t":"Отлично! Ты готов вернуться туда, Бамхам?"},{"a":"bjorn","t":"Мы не знаем, что это такое... но вряд ли что-то хорошее."},{"a":"bjorn","t":"Наша задача — выяснить, кто за этим стоит!"},{"a":"engineer","t":"Удачи! И... будьте осторожны при обращении с загадочной техникой!"}]}]},{"id":"hemma","name":"Гемма","chapters":[{"id":"hemma_01","i":1,"title":"Нависшая тень","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"hemma","t":"...и тогда гиблин пал, но до этого успел нанести несколько ударов моим спутникам."},{"a":"hemma","t":"Пожалуйста, позаботься об их исцелении."},{"a":"priest","t":"Конечно. Я в спешном порядке обработаю их раны."},{"a":"lilu","t":"Привет! Я слышала, что в городе появился новый заклинатель."},{"a":"lilu","t":"Я Лилу! Рада с вами познакомиться!"},{"a":"hemma","t":"Ты права, юная Лилу. Нас зовут Хемма. "},{"a":"lilu","t":"«Нас»?.."},{"a":"hemma","t":"Да. Некромантия не проходит бесследно для тех, кто ее практикует..."},{"a":"hemma","t":"Часть тебя остается за Покровом, а другие сущности приходят из-за него..."},{"a":"hemma","t":"Эти способности... нас изменили. К лучшему, конечно."},{"a":"lilu","t":"Некромантия, говорите?! А это разве не... опасно?"},{"a":"hemma","t":"Чрезвычайно. Но нас больше не удовлетворяют простые фокусы."},{"a":"hemma","t":"А теперь позволь откланяться, нам нужно быть в другом месте. Прощай."},{"a":"lilu","t":"Некромант... Это довольно темная магия, Поллукс! Но я впервые вижу ее настоящего практика!"},{"a":"lilu","t":"Кажется, она не такая уж плохая... Верно?"}]},{"id":"hemma_02","i":2,"title":"Любой ценой","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"elderowen","t":"Некромант?.."},{"a":"elderowen","t":"Не знаю даже, что обо всем этом думать..."},{"a":"hemma","t":"Вы правы, что беспокоитесь. Некромантия — опасное искусство, поглощающее менее значительных существ..."},{"a":"hemma","t":"Но мы в любом случае таковыми не являемся."},{"a":"elderowen","t":"А как насчет путешественников, которые отправляются с вами? Вы не высасываете из них жизнь, чтобы усилить свои заклинания?"},{"a":"hemma","t":"Только с их согласия. Эффекты при этом не постоянны."},{"a":"hemma","t":"И мы щедро платим их за услуги."},{"a":"elderowen","t":"Полагаю, вы все-таки делаете добро..."},{"a":"elderowen","t":"Хорошо. Полагаю, вы можете стать официально одобренным защитником нашего города."},{"a":"hemma","t":"Ваше одобрение нам было не нужно... но мы вас благодарим."},{"a":"elderowen","t":"А что привело вас в наш город?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Мы просто ищем знания и силу. "},{"a":"hemma","t":"Есть... задача, которую мы должны выполнить."},{"a":"elderowen","t":"Как туманно..."},{"a":"hemma","t":"И так оно и останется. Прощайте."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"Сколько печали в этих глазах..."}]},{"id":"hemma_03","i":3,"title":"Враг внутри","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"herbalist","t":"Незрелые живые корни и суперплотная жуткая эктоплазма. Что-нибудь еще?"},{"a":"hemma","t":"Это все. За остальным зайдем в лавку."},{"a":"herbalist","t":"Спасибо, приходите еще!"},{"a":"hemma","t":"<c4>Не забудь о мрачных когтях.</c4>"},{"a":"hemma","t":"Ах да. Пару мрачных когтей, пожалуйста."},{"a":"herbalist","t":"Что это сейчас было?.."},{"a":"hemma","t":"Не обращай внимания. Просто пассажир, так сказать."},{"a":"hemma","t":"<c4>Выпусти-меня-выпусти-меня-выпусти-меня.</c4>"},{"a":"hemma","t":"Уф. Да успокойся ты!"},{"a":"hemma","t":"Сдачу можешь оставить себе. Прощай."},{"a":"herbalist","t":"Спасибо за совет... и кошмары."}]},{"id":"hemma_a","i":3,"title":"Среди бессмертных","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"donovan","t":"Незрелые живые корни? Интересный выбор."},{"a":"hemma","t":"А что такого?"},{"a":"donovan","t":"Живые корни — это мощные реагенты для многих заклинаний, связанных с молодостью и продолжительностью жизни."},{"a":"donovan","t":"Не алхимик ли ты? Не долголетия ли ищещь?"},{"a":"hemma","t":"Ты спрашиваешь возраст у дамы? Как... неприлично."},{"a":"hemma","t":"Мы не алхимик. Кровавые жертвоприношения гораздо более эффективны."},{"a":"donovan","t":"А, некромантия! Сфера деятельности, заслуживающая уважения, но неправильно понимаемая другими."},{"a":"hemma","t":"Что касается нашего возраста... то мы давным-давно перестали считать."},{"a":"donovan","t":"Это мне определенно знакомо. После первых нескольких веков десятилетия так и летят!"},{"a":"donovan","t":"Становится одиноко среди всех этих однодневок, правда?"},{"a":"hemma","t":"Нам не одиноко. А тебе не стоит совать нос в дела некроманта."},{"a":"donovan","t":"Конечно. И желания нет вмешиваться. Прощай!"},{"a":"donovan","t":"Странная некромантка... Мы раньше не встречались?"},{"a":"donovan","t":"Фэрлин?.."}]},{"id":"hemma_04","i":4,"title":"Экзорцизм","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Не волнуйся, Хемма. Я здесь! Со мной Фрейя!"},{"a":"priest","t":"Хемма, да? Прошу, расслабься. Наполнись силой экзорцизма..."},{"a":"hemma","t":"Что-то мы не помним, чтобы просили о твоей помощи."},{"a":"hemma","t":"<c4>Отвалите, детишки. Я никуда уходить не собираюсь.</c4>"},{"a":"lilu","t":"А-а-а-а! Оно захватывает контроль! Быстрее, Фрейя!"},{"a":"priest","t":"Я... не могу! Что-то блокирует мои молитвы..."},{"a":"hemma","t":"Это мы. Прекратите."},{"a":"priest","t":"Ты... добровольно носишь в себе этого злого духа?!"},{"a":"hemma","t":"Признаюсь, со временем он немного сошел с ума."},{"a":"hemma","t":"<c4>Это я здесь жертва! Выпустите меня!</c4>"},{"a":"hemma","t":"Ух. Скорее грубый, чем злой, уверяю вас."},{"a":"hemma","t":"Это дело тебя не касается. Прошу, не вмешивайся, Фрейя."},{"a":"priest","t":"Ох уж эти некроманты... вечно играют с силами, которые не могут понять!"},{"a":"lilu","t":"Все нормально, Фрейя! Я уверена, она знает, что делает!"},{"a":"lilu","t":"Да?.."}]},{"id":"hemma_05","i":5,"title":"Два разума в одном теле","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"hemma","t":"<c4>Похоже, секрет снова раскрыт. Готова покинуть город?</c4>"},{"a":"hemma","t":"Это все ТЫ. Веди ты себя потише, все было бы гораздо проще."},{"a":"hemma","t":"Невзирая ни на что, мы пока не уходим. Этот город подает надежды."},{"a":"hemma","t":"<c4>Ладно. Как насчет того, чтобы выпустить меня хоть раз?</c4>"},{"a":"hemma","t":"С-совершенно исключено. Тебя и так трудно держать под контролем."},{"a":"hemma","t":"<c4>Выпусти-выпусти-выпусти.</c4>"},{"a":"hemma","t":"Я делаю это ради тебя, Клод."},{"a":"hemma","t":"Прошу, помни это."}]},{"id":"hemma_06","i":6,"title":"Лживое наследие","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Фэрлин!"},{"a":"hemma","t":"Да?"},{"a":"lilu","t":"Я так и знала! Хемма — ненастоящее имя! Ты чудовище, Фэрлин!"},{"a":"hemma","t":"О-о! Да ты хитрая маленькая плутовка."},{"a":"hemma","t":"Это правда. Похоже, ты хорошо навела справки."},{"a":"hemma","t":"Возможно, ты также слышала об Ариэль Безумной? Или об Астрид Падшей?"},{"a":"lilu","t":"Я о них читала... но они исчезли многие десятилетия назад! Не может же быть, что они..."},{"a":"hemma","t":"Это мы, конечно. К сожалению, мы сталкиваемся с серьёзными гонениями, и от имён приходится отказываться..."},{"a":"lilu","t":"Ты чудовище! Тебя нужно остановить!"},{"a":"hemma","t":"И как ты намерена это сделать? «Хемма» невиновна. Кто поверит в твою дикую историю?"},{"a":"hemma","t":"Вот разве что ты сама меня остановишь..."},{"a":"lilu","t":"Пф!"}]},{"id":"hemma_07","i":7,"title":"Сопряжение душ","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"hemma","t":"Все шныряешь?"},{"a":"lilu","t":"Я слежу за тобой. Ты и твои подозрительные монологи..."},{"a":"hemma","t":"Ах да. Познакомься с Клодом, нашим мужем. Бывали у него времена и получше."},{"a":"hemma","t":"<c4>Выпустите меня!</c4>"},{"a":"lilu","t":"Что с ним случилось?.."},{"a":"hemma","t":"Ужасный несчастный случай, связанный с некромантией. Глупая ошибка привела его на край гибели."},{"a":"hemma","t":"Мы на земле творим такие грехи, что загробная жизнь для нас, некромантов — ужасающая перспектива."},{"a":"hemma","t":"Мы не могли спасти его тело, но сделали всё возможное... и спасли его душу."},{"a":"lilu","t":"Сопряжение душ? Это заклинание требует многолетних исследований для подготовки соответствующего сосуда..."},{"a":"hemma","t":"Так и есть. С учётом обстоятельств, нам пришлось импровизировать."},{"a":"lilu","t":"Импровизировать? Ты же не хочешь сказать, что... привязала душу Клода к себе?!"},{"a":"lilu","t":"Тело не выдержит две души! Результатом стала бы..."},{"a":"hemma","t":"Сокрушающая разум боль. Безумие. Хуже, чем ты можешь себе представить."},{"a":"lilu","t":"Хемма... Почему?.. Как?.."},{"a":"hemma","t":"Все просто, Лилуша. У нас нет права на... ошибку."}]},{"id":"hemma_08","i":8,"title":"Поручение столетия","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Душа слишком сильна, её не изгнать... Может, привязать её к чему-то другому?"},{"a":"hemma","t":"Ты ужасно сговорчивая. У тебя появился интерес к некромантии?"},{"a":"lilu","t":"Нет! Я ненавижу тебя и всё, что ты сделала!"},{"a":"lilu","t":"Насколько я понимаю, если этот Клод вырвется на свободу, здесь никому не поздоровится."},{"a":"lilu","t":"Я помогу тебе исправить это безобразие, но на этом всё!"},{"a":"hemma","t":"Благородное чувство. Но чем может помочь простой ребёнок?"},{"a":"lilu","t":"Подготовка надлежащего сосуда потребует десятилетий исследований и материалов..."},{"a":"hemma","t":"Это не проблема. Узри же."},{"a":"lilu","t":"Ой! Откуда у тебя всё это?.. Даже чёрные алмазы!"},{"a":"hemma","t":"Прошедшие десятилетия не были потрачены впустую. Наше время истекает."},{"a":"hemma","t":"Осталось найти подходящее место для проведения ритуала. Мы боимся, что такого может и не быть."},{"a":"lilu","t":"Правильно. У души должна быть духовная связь с местом, иначе привязка не получится."},{"a":"hemma","t":"<c4>Или можно просто отпустить старого доброго Клода Фавиуса на свободу! Он заведёт много друзей!</c4>"},{"a":"lilu","t":"Погоди... Ты сказала «Фавиус»?"}]},{"id":"hemma_09","i":9,"title":"Замок с привидениями","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"hemma","t":"Какое восхитительное место с привидениями."},{"a":"lilu","t":"Ужасное место. Ни одному здравомыслящему человеку не надо сюда приходить."},{"a":"lilu","t":"Но самое главное: согласно моим исследованиям..."},{"a":"lilu","t":"...много веков назад здесь правил безумный король из рода Фавиусов."},{"a":"lilu","t":"Может быть, Клод — его дальний родственник? Надеюсь, он не был причастен к гибели королевства..."},{"a":"hemma","t":"Мы чувствуем это. Мы связаны с этим местом. Это оно."},{"a":"hemma","t":"Мы в большом долгу перед тобой, Лилу. Но теперь ты должна оставить нас в покое."},{"a":"lilu","t":"Хемма... Удачи."}]},{"id":"hemma_10","i":10,"title":"Пока смерть не разлучит нас","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"hemma","t":"Тёмное уединённое место, полное привидений и некромантской энергии..."},{"a":"hemma","t":"Как долго мы искали такое место?"},{"a":"hemma","t":"Теперь нужно найти подходящий сосуд..."},{"a":"hemma","t":"Не нужно слов. Мы прекрасно знаем, чего ты желаешь."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Доспехи самого безумного короля, навечно привязанные к этому месту."},{"a":"hemma","t":"<c1>Сопряжение душ!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Ух... Мы это чувствуем... или я?.."},{"a":"hemma","t":"Я забыла это чувство одиночества..."},{"a":"hemma","t":"Я страдала целую вечность, чтобы спасти тебя, дорогой. Потому что знаю, что ты поступил бы точно так же."},{"a":"hemma","t":"Отважные искатели приключений обязательно придут. Сразись с ними: резня исцелит твою измученную сущность."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Прощай, любимый. Но только смерть разлучит нас по-настоящему."}]},{"id":"hemma_epilogue","i":11,"title":"Эпилог","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>ГЛУПЦЫ-Ы-Ы!!! ВЫ СМЕЕТЕ СТУПАТЬ НА МОИ ЗЕМЛИ?</c4>"},{"a":"sia","t":"Какой неприятный враг!"},{"a":"Castle_Boss","t":"<c4>МУА-ХА-ХА-ХА! НИЧТОЖНЫЕ СМЕРТНЫЕ!</c4>"},{"a":"argon","t":"Леди Сиа! Рудо! Отступаем!"},{"a":"rudo","t":"Никогда! Я не уступлю ему ни пяди!"},{"a":"yami","t":"Я нашла выход. Быстрее!"},{"a":"rudo","t":"Тьфу! Я ещё вернусь, банка ты консервная! Слышишь меня?"},{"a":"Castle_Boss","t":"<c4>ВОЗВРАЩАЙТЕСЬ, КОГДА СМОЖЕТЕ ДАТЬ ОТПОР!</c4>"},{"a":"Castle_Boss","t":"<c4>СКАЖИТЕ СВОИМ ВЕЛИЧАЙШИМ ГЕРОЯМ, ЧТО КОРОЛЬ-ТИРАН ЖДЁТ!</c4>"}]}]},{"id":"donovan","name":"Донован","chapters":[{"id":"donovan_01","i":1,"title":"Оригинальный рецепт","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"herbalist","t":"Добро пожаловать в «Лекарственную лавку Марибель». Чем могу помочь?"},{"a":"donovan","t":"Леди Марибель, да? Я хотел бы лично похвалить ваше последнее творение."},{"a":"donovan","t":"Как изобретатель зелья возобновления, скажу, что ваш модифицированный чертеж воистину гениален!"},{"a":"donovan","t":"Простое добавление щепотки туманоцвета — это потрясающее улучшение!"},{"a":"herbalist","t":"Погоди-ка... Вы хотите сказать, что вы тот самый Донован? Не может быть!"},{"a":"herbalist","t":"Чертеж зелья возобновления был изобретен около 700 лет назад..."},{"a":"herbalist","t":"Даже будучи эльфом, вы не выглядите старше 150!"},{"a":"donovan","t":"Вы слишком добры, леди Марибель."},{"a":"donovan","t":"Скажем так, не все мои чертежи в продаже..."},{"a":"donovan","t":"Но я уверен, что такой мастер-алхимик, как вы, без труда бы их выучил."},{"a":"donovan","t":"А теперь можно ли мне взглянуть на этот туманоцвет?"}]},{"id":"donovan_02","i":2,"title":"Изобильный край","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"donovan","t":"Замечательно... В этих краях даже обычные яблоки имеют превосходное качество."},{"a":"donovan","t":"Интересно, как такое возможно?.."},{"a":"lilu","t":"Если кто и мог бы это объяснить, то это Джунипер!"},{"a":"lilu","t":"Ой, простите! Я не хотела помешать вашему разговору с этим... деревом."},{"a":"donovan","t":"О, юная леди в широкополой шляпе со своей верной совой..."},{"a":"donovan","t":"Несомненно, вы госпожа Лилу."},{"a":"lilu","t":"Все верно! Да и вы, сэр Донован, очевидно, не нуждаетесь в представлении!"},{"a":"donovan","t":"Я много слышал об одаренной молодой ученице в этом городе и тоже рад знакомству."},{"a":"donovan","t":"Вы что-то говорили, госпожа Лилу?.."},{"a":"lilu","t":"Ах да! Джунипер постоянно говорит, что земля вокруг города полна жизни..."},{"a":"lilu","t":"Это, по ее словам, одна из причин, почему она так любит заниматься здесь садоводством."},{"a":"lilu","t":"В любом случае, я направлялась в пещеры Авроры. Приятно было познакомиться, сэр Донован!"},{"a":"donovan","t":"Надеюсь, мы скоро встретимся снова."},{"a":"donovan","t":"Хм... Возможно, эта юная леди что-то знает..."},{"a":"donovan","t":"Керн... истощен? Похоже, в этом королевстве во всем гораздо больше жизненных сил."},{"a":"donovan","t":"Следует нанести визит этой садовнице. Если здешние ингредиенты помощнее..."},{"a":"donovan","t":"...я должен этим воспользоваться."}]},{"id":"donovan_03","i":3,"title":"Под маской","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Вызывали меня, госпожа Сиа?"},{"a":"sia","t":"А, Лилу. Спасибо, что пришла так быстро."},{"a":"sia","t":"Полагаю, ты уже познакомилась с Донованом?"},{"a":"lilu","t":"О да! Он же легенда среди алхимиков! Я так рада, что мы встретились!"},{"a":"sia","t":"Веди себя с ним крайне осторожно."},{"a":"lilu","t":"Ч-что?! Но он же такой джентльмен! И столько всего знает..."},{"a":"sia","t":"Внешность может быть обманчива. За его молодым лицом скрывается хитрый тысячелетний гений."},{"a":"lilu","t":"Тысячелетний?! Это неслыханно даже для эльфов! Вы думаете, что..."},{"a":"sia","t":"Да. Некоторые считают, что, возможно, он открыл какой-то эликсир бессмертия."},{"a":"lilu","t":"Ого! Я бы не прочь добавить такой рецепт в свой гримуар!"},{"a":"sia","t":"Как и многие правители. Подозреваю, сам император Керна пляшет под его дудку."},{"a":"lilu","t":"Политика — такая сложная штука..."},{"a":"lilu","t":"Но спасибо! Я буду осторожна рядом с ним!"},{"a":"sia","t":"Я знала, что ты поймешь."},{"a":"sia","t":"Что касается меня, я позабочусь о том, чтобы он держался подальше от нашего... впечатлительного короля."},{"a":"lilu","t":"Да... так, вероятно, к лучшему."}]},{"id":"donovan_a","i":3,"title":"Сделка за десять золотых","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"leather","t":"Эй, дружок с зельями! Минутки не найдется?"},{"a":"donovan","t":"Ух... бродяги."},{"a":"donovan","t":"Кому обязан такой... честью?"},{"a":"leather","t":"Я — Тамас, кожевник."},{"a":"leather","t":"Я слышал, дружище, ты можешь сварганить крутой эликсир бессмертия. А мне можно бутылочку?"},{"a":"donovan","t":"Понятия не имею, где вы такое услышали."},{"a":"donovan","t":"Даже если бы это была правда, вы можете быть уверены, что я не стал бы отдавать что-либо столь ценное."},{"a":"leather","t":"Я дам тебе за него десять золотых."},{"a":"donovan","t":"Исключено. За этот рецепт велись войны! Императоры со всего мира умоляют дать им хотя бы попробовать!"},{"a":"leather","t":"Какой ты неуступчивый, дружище. Последнее предложение — пятнадцать золотых."},{"a":"donovan","t":"Тебе запах кожи мозги затуманил, бродяга? Я бы не расстался с этим рецептом даже за все золото мира!"},{"a":"donovan","t":"Мне пора идти. Прошу больше со мной никогда не разговаривать."},{"a":"leather","t":"Вот зараза, чуть-чуть не хватило."},{"a":"leather","t":"Видать, придется снова искать угощение для овец..."}]}]},{"id":"lilu","name":"Лилу","chapters":[{"id":"lilu_01","i":1,"title":"Одаренная ученица","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Ну что, Поллукс? Что думаешь об этом новом заклинании? Идеальное, да?"},{"a":"lilu","t":"Да, на этот раз мы точно справимся!"},{"a":"herbalist","t":"Доброе утро, Лилу! Пришла за еженедельной партией живых корней?"},{"a":"lilu","t":"Да, спасибо, Марибель!"},{"a":"herbalist","t":"Ты на этой неделе много заказала! Что твой мастер со всем этим делает?"},{"a":"lilu","t":"Честно говоря, половина из этого для меня. Я решила серьезно заняться учебой!"},{"a":"herbalist","t":"Да? И что учишь?"},{"a":"lilu","t":"Исцеляющие заклинания! Всю прошедшую неделю лечила порезы и ушибы в тренировочном зале!"},{"a":"herbalist","t":"Уверена, герои рады, когда ты рядом."},{"a":"herbalist","t":"...И Аргон тоже!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"М-мне нужно идти! Спасибо!"}]},{"id":"lilu_02","i":2,"title":"Мрачные вести","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Вот, мастер Гримар. Живые корни, присланные на этой неделе."},{"a":"wizard","t":"Спасибо, Лола. А вот тебе домашнее задание на сегодня."},{"a":"lilu","t":"О! Магический фолиант! Об искусстве исцеления?"},{"a":"lilu","t":"«Злодейский справочник злословия»?"},{"a":"lilu","t":"Какая сложная книга! Тут даже есть целый раздел о проклятиях!"},{"a":"wizard","t":"...Проклятиях?"},{"a":"wizard","t":"Хм... Проклятиях?"},{"a":"lilu","t":"Мастер?"},{"a":"wizard","t":"35 лет назад в этот самый день... я..."},{"a":"lilu","t":"Мастер Гримар?!"},{"a":"wizard","t":"...Забыл. А ты кто, дитя мое?"},{"a":"lilu","t":"...Я Лилу, ваша ученица. Можно Лола..."},{"a":"lilu","t":"Ладно, неважно. Буду изучать эту книгу. Спасибо, Грим."}]},{"id":"lilu_03","i":3,"title":"Помутненный рассудок","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"...Добавить щепотку серебряной пыли, и... готово!"},{"a":"lilu","t":"Посмотри, как светится! Неплохо, да, Поллукс?"},{"a":"lilu","t":"Если верить «Злодейскому справочнику злословия», это зелье должно..."},{"a":"wizard","t":"Лола, что за шум? Я вообще-то пытаюсь поспать!"},{"a":"lilu","t":"Мастер Гримар! С помощью вашей книги я сварила очень сложное зелье! Оно должно..."},{"a":"wizard","t":"Что-что?!"},{"a":"wizard","t":"Тогда давай его сюда! Попробуем!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Мастер Гримар?"},{"a":"wizard","t":"Лилу! Мне ну-ну-нужно ос-освободиться! Вы-выпусти меня из р-разума этого остолопа!"},{"a":"lilu","t":"М-мастер Гримар! Вы в порядке?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"Буэ! Какой-то фруктовый вкус!"},{"a":"wizard","t":"Неплохо, Лола. А теперь возвращайся к своим повседневным делам."},{"a":"lilu","t":"...Это было НЕнормально."}]},{"id":"lilu_a","i":3,"title":"Вековой копитель","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"lilu","t":"Гримар, а ты не говорил, что у тебя есть вторая <c1>коллекционная книга</c1>!"},{"a":"wizard","t":"<c1>Коллекционная книга</c1>?.. Что-то знакомое..."},{"a":"lilu","t":"Ого! Да здесь полно информации! <c1>Дамоклов меч</c1>... <c1>Янтарная цитадель</c1>..."},{"a":"lilu","t":"<c1>Великая палочка Гримара</c1>?.. Это ты ее назвал?"},{"a":"lilu","t":"Так много страниц! Вот так коллекционер!"},{"a":"sundragon","t":"Да уж, было времечко!"},{"a":"wizard","t":"Это ты, Солдра, старый друг?"},{"a":"lilu","t":"Ого! Ребята, вы знакомы?"},{"a":"sundragon","t":"Конечно. Молодой Гримар был просто влюблен в свою коллекционную книгу."},{"a":"sundragon","t":"Кажется, она позволила ему получить престижное звание среди людей-единомышленников... «Ботан», что ли?"},{"a":"lilu","t":"Ой..."},{"a":"sundragon","t":"Мы познакомились, когда он искал редкости, и вместе создали <c1>котел синтеза</c1>."},{"a":"sundragon","t":"Он день и ночь напролет синтезировал сотни предметов... а в полнолуние еще больше!"},{"a":"lilu","t":"Столько усилий... а его коллекция все еще не завершена!"},{"a":"lilu","t":"Клянусь, я исцелю вас, мастер Гримар! Вы должны завершить дело своей жизни!"},{"a":"sundragon","t":"Время жестоко по отношению к человечеству, это безусловно. Желаю тебе удачи в приключениях, малыш."}]},{"id":"lilu_04","i":4,"title":"Конец королевского рода","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"С мастером Гримаром что-то не так..."},{"a":"lilu","t":"Его голос... Казалось, будто кто-то говорил внутри него!"},{"a":"lilu","t":"Может быть, мы имеем дело со сложным заклинанием превращения?"},{"a":"lilu","t":"Или, может быть, даже..."},{"a":"leather","t":"Блин, Лилу! На королевском пиру что-то пошло не так!"},{"a":"lilu","t":"Тамас? Что происходит?"},{"a":"leather","t":"Вроде посторонний в замке. Как-то жутковато!"},{"a":"lilu","t":"Посторонний!.. И это в первый день Аргона в качестве рыцаря!"},{"a":"lilu","t":"Спасибо, Тамас, мне нужно идти!"},{"a":"lilu","t":"О нет!.. Что здесь происходит?!"},{"a":"lilu","t":"Аргон, где же ты?!"},{"a":"king","t":"А-а-а..."},{"a":"lilu","t":"КОРОЛЬ РЕЙНГОЛЬД?! Вы в порядке?!"},{"a":"king","t":"А-а-а... Моя драгоценная жизнь... утекает..."},{"a":"lilu","t":"Плохо дело!.."},{"a":"lilu","t":"Сосредоточься, Лилу! Вспомни обучение мудреца!"},{"a":"lilu","t":"Король Рейнгольд! Не шевелитесь! <c1>Исцеление</c1>!"},{"a":"king","t":"Бесполезно... Пожалуйста... сохраните мой красивый труп..."},{"a":"lilu","t":"Никакого эффекта..."},{"a":"lilu","t":"О нет... Может это был... яд?"},{"a":"lilu","t":"Так же было и с моими родителями!.. Но в этот раз у меня все получится!"},{"a":"lilu","t":"<c1>Мощное очищение от яда!</c1>"},{"a":"king","t":"А-а-а-а... Что?"},{"a":"lilu","t":"Король Рейнгольд! Как вы себя чувствуете?"},{"a":"lilu","t":"Погодите-ка... Эта чаша защитила вас от сюрикэна! Вы вообще не пострадали!"},{"a":"king","t":"Ой, правда? Видимо, я отреагировал немного эмоциональнее, чем следовало."},{"a":"king","t":"Все-таки смерть монарха — это драматическое событие."},{"a":"lilu","t":"Ох! Рейнгольд!"}]},{"id":"lilu_05","i":5,"title":"Разговор о ядах","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Ух... Вот это пронесло... как бы."},{"a":"lilu","t":"Если бы Рейнгольда действительно отравили... я вряд ли бы смогла ему помочь."},{"a":"lilu","t":"Нужно сосредоточить свои усилия на другом. Чтобы никто не понес потери, как я..."},{"a":"lilu","t":"Госпожа Сиа!"},{"a":"sia","t":"А, наша звезда! Разбираться с непрошеным гостем отправили рыцаря. Можешь спать спокойно."},{"a":"lilu","t":"(Рыцаря? Удачи, Аргон!)"},{"a":"sia","t":"Спасибо за... спасение нашего короля, несмотря на обстоятельства."},{"a":"lilu","t":"Да не за что! Но случись такое снова, я не уверена, что смогла бы помочь..."},{"a":"lilu","t":"Госпожа Сиа, вам известно что-нибудь о ядах?"},{"a":"sia","t":"Конечно. Например, аконит, также как известный как волчья отрава, убивает ужасно эффективно."},{"a":"sia","t":"Но лично мне больше всего по нраву рицин. Бессимптомный, смертоносный, легкодоступный..."},{"a":"lilu","t":"Э-э... А о средствах против них?"},{"a":"sia","t":"Ой. Я об этом как-то особо и не задумывалась."},{"a":"lilu","t":"...Забудьте, что я это спрашивала."}]},{"id":"lilu_06","i":6,"title":"Учитель и ученик","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Я вернулась, мастер Гримар!"},{"a":"wizard","t":"А, с возвращением, Лола."},{"a":"lilu","t":"Вы можете в это поверить? Короля чуть не убили!"},{"a":"wizard","t":"Правда?.."},{"a":"lilu","t":"Убийца появился из ниоткуда и запустил в него сюрикэном!"},{"a":"lilu","t":"И тогда я поспешила на помощь, когда он умирал на полу!.."},{"a":"wizard","t":"Э-э... Напомни, ты кто?"},{"a":"lilu","t":"Ах да. Ваше состояние... Нужно вернуться к этому вопросу!"},{"a":"lilu","t":"Возможно, это тоже яд..."},{"a":"lilu","t":"Поглядим-ка... Гримар очень стар..."},{"a":"lilu","t":"Как думаешь, Поллукс?"},{"a":"lilu","t":"Да, нужно порасспрашивать в городе!"},{"a":"lilu","t":"Возможно, кто-то из пожилых жителей помнит, как вел себя Гримар, когда был помоложе..."}]},{"id":"lilu_07","i":7,"title":"Знания предков","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Мастер Теодор!"},{"a":"master","t":"Это же Лилу! Чем я могу тебе помочь?"},{"a":"lilu","t":"А вы не могли бы рассказать мне о Гримаре в молодости?.."},{"a":"lilu","t":"...Раз уж вы, э-э... старый и все такое."},{"a":"master","t":"Хо-хо-хо! Конечно, конечно."},{"a":"master","t":"Старый Гримар всегда был немного... эксцентричным."},{"a":"master","t":"Но когда я был мелким, помнится, ум у него был куда острее. Даже в шахматах мы были равны."},{"a":"master","t":"Но вот после того путешествия в руины Кроноса... он, насколько я помню, всегда чувствовал себя немного не в своей тарелке."},{"a":"lilu","t":"Руины Кроноса! Это же такое опасное место!"},{"a":"lilu","t":"...Целая цивилизация превратилась в руины из-за исследования магии времени..."},{"a":"lilu","t":"Там полно магических аномалий! Что же Гримар заполучил при посещении этого места?"},{"a":"lilu","t":"Ты прав, Поллукс, это наша единственная зацепка. Мы должны заняться расследованием!"},{"a":"lilu","t":"Но нам понадобится охрана... Попросить Аргона, что ли?.."},{"a":"lilu","t":"Нет! Что если вихрь времени внезапно превратит его в старика? Или сделает с ним то же, что и с Гримаром..."},{"a":"lilu","t":"...Я могу вспомнить только одного человека, который мог бы нам помочь..."},{"a":"lilu","t":"Будет нелегко, Поллукс! Но мы должны попытаться!"},{"a":"lilu","t":"Спасибо, Теодор! Вы очень помогли!"},{"a":"master","t":"Не за что, Лилу! До встречи!"},{"a":"master","t":"..."},{"a":"master","t":"...Вот ведь умная сова!.."}]},{"id":"lilu_08","i":8,"title":"Общее дело","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Господин Рудо, прошу вас! Не уходите, мне нужно с вами поговорить!"},{"a":"rudo","t":"Девочка, уходи, я не хочу это слышать."},{"a":"rudo","t":"Иди гулять со своей совой куда-то еще!"},{"a":"lilu","t":"Я знаю, что вы не любите заклинателей... но мне нужна ваша помощь!"},{"a":"lilu","t":"Мне нужно отправиться вглубь руин Кроноса, а сама я пойти не могу! "},{"a":"rudo","t":"Так попроси этого пацана Аргона, он же твой рыцарь в сияющих доспехах."},{"a":"lilu","t":"Он... э-э, в данный момент чем-то занят..."},{"a":"lilu","t":"Значит, вас просить смысла нет..."},{"a":"rudo","t":"Все верно, девочка."},{"a":"tavern","t":"Как жаль, дорогуша."},{"a":"tavern","t":"Я слышала, что повелителя циклопов из руин Кроноса никогда не побеждали в поединке один на один..."},{"a":"tavern","t":"Для сопровождения Лилу через руины нужен исключительный воин!"},{"a":"rudo","t":"Никогда не побеждали, говоришь?"},{"a":"rudo","t":"Ладно, согласен. Сколько мне придется крушить?"},{"a":"lilu","t":"Уверена, что много!"},{"a":"lilu","t":"Понимаете, мне нужно найти источник потока времени в различных кристаллах и изолировать..."},{"a":"rudo","t":"Короче. Что надо крушить?"},{"a":"lilu","t":"Монстров и магические кристаллы."},{"a":"rudo","t":"Хорошо, принято. За тобой должок, девочка."},{"a":"lilu","t":"Фантастика! Большое спасибо, господин Рудо!"},{"a":"rudo","t":"Поблагодаришь после нашего путешествия, девочка. Это тебе не прогулка в парке."},{"a":"lilu","t":"Я залечу вам раны, если монстров, с которыми вы столкнетесь, будет слишком много!"},{"a":"rudo","t":"Пф. Это вряд ли."},{"a":"lilu","t":"И тебе тоже спасибо, Найя!"},{"a":"tavern","t":"Всегда пожалуйста, дорогуша."}]},{"id":"lilu_09","i":9,"title":"Зеркальный мир","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Я займу циклопов! Иди вперед!"},{"a":"rudo","t":"Ну же, толстоклопы! Сейчас я вам задам перцу!"},{"a":"lilu","t":"Ясно! Удачи!"},{"a":"lilu","t":"Вот он... Чертог времени. И согласно моим исследованиям..."},{"a":"lilu","t":"Этот водоем должен быть соединен с отделившейся временной линией!"},{"a":"lilu","t":"С параллельной вселенной, где город Кронос по-прежнему процветает..."},{"a":"lilu","t":"Смотри, Поллукс! Если вглядеться в воду... можно что-то увидеть!"},{"a":"lilu","t":"Похоже, что жители Кроноса живут обычной жизнью, где-то там..."},{"a":"lilu","t":"Эй... Этот парень машет нам рукой?"},{"a":"lilu","t":"Он очень похож на... Гримара?!"}]},{"id":"lilu_10a","i":10,"title":"Проклятие вечных лет","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Гримар!!! Выпейте!"},{"a":"wizard","t":"А? Что-то... знакомое."},{"a":"lilu","t":"Это специальная микстура, приготовленная на воде Кроноса..."},{"a":"wizard","t":"...Стабилизированная и дважды обработанная нитями судьбы?"},{"a":"lilu","t":"...и приведенная в материальную форму с помощью дистиллированной эктоплазмы."},{"a":"wizard","t":"С щепоткой глубоководного коралла для вкуса!"},{"a":"wizard","t":"Впечатляющая работа, Лилу. Учителю есть чем гордиться."},{"a":"lilu","t":"Г-гримар... Вы снова в порядке! Сработало!"},{"a":"wizard","t":"Какие необычные ощущения... будто туман только что покинул мой разум..."},{"a":"lilu","t":"Я примерно представляю, как работает зелье, но... есть кое-чего я не понимаю."},{"a":"lilu","t":"Мы видели вас в водоеме! В отделившейся временной линии!"},{"a":"wizard","t":"Хе-хе! Правда? У меня есть теория на этот счет..."},{"a":"wizard","t":"Поллукс, дорогой. Ты не можешь слетать за стариком Оуэном? Полагаю, многое нужно объяснить..."}]},{"id":"lilu_10b","i":11,"title":"Теория о разделении времени","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"elderowen","t":"Мой старый друг! Вот это история!"},{"a":"lilu","t":"Мне самой трудно в это поверить... Гримар — выживший из города Кроноса?"},{"a":"wizard","t":"Когда заклинание времени пошло наперекосяк, весь город был переброшен в другую временную линию."},{"a":"elderowen","t":"Я помню тот день, словно это было вчера. Целый город исчез в мгновение ока!"},{"a":"elderowen","t":"Среди руин мы нашли лишь одиноко бродящего ребенка..."},{"a":"lilu","t":"Это был Гримар? Трудно представить вас обоих детьми..."},{"a":"elderowen","t":"Хе-хе! Мы быстро подружились, верно?"},{"a":"wizard","t":"Это да. Я учился, чтобы стать чародеем и самому изучить это странное происшествие."},{"a":"wizard","t":"Если глаза Лилу не обманули, то я верю, что другой Гримар существует."},{"a":"lilu","t":"Гримар, которого мы видели... Значит, вы все же существуете в другой временной линии?!"},{"a":"wizard","t":"Похоже на то. Сначала не было никаких последствий, но..."},{"a":"wizard","t":"По мере того как оба Гримара росли, наши личности и жизненный опыт стали постепенно различаться."},{"a":"lilu","t":"И растущий магический парадокс все больше обременял ваш разум..."},{"a":"lilu","t":"Понимаю! Выпив зелье из руин Кроноса, вы устанавливаете связь с другой временной линией!"},{"a":"wizard","t":"Такова моя теория. Уверен, другой Гримар будет за это благодарен."},{"a":"lilu","t":"Ох... Тут сразу не разобраться. Думаю, мне нужно поспать... Ты идешь, Поллукс?"},{"a":"elderowen","t":"Что касается нас, старина Грим, нам многое нужно наверстать!"},{"a":"wizard","t":"Говори за себя, старый хрыч! Я никогда не чувствовал себя моложе!"}]},{"id":"lilu_epilogue","i":12,"title":"Эпилог","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Привет, Гримар! Вот новый рецепт. Должно действовать немного дольше!"},{"a":"wizard","t":"Замечательное улучшение! Родители бы тобой гордились."},{"a":"lilu","t":"Если бы я начала изучать алхимию чуть раньше..."},{"a":"wizard","t":"У меня такие же чувства. Если бы я полностью контролировал свои возможности..."},{"a":"lilu","t":"...Все в порядке. Я решила сосредоточиться на будущем. Чтобы стать лучше и спасти других от этой участи."},{"a":"lilu","t":"...Уверена, мои родители хотели бы именно этого."},{"a":"wizard","t":"Ты так выросла... Я едва узнаю тебя."},{"a":"wizard","t":"Вообще-то... кто ты такая?"},{"a":"lilu","t":"О нет! Эффект уже проходит! Мне лучше..."},{"a":"wizard","t":"Хе-хе-хе! Да шучу я. У меня хорошее предчувствие на этот счет."},{"a":"wizard","t":"А теперь, пока у меня в голове ясно, не хочешь ли немного поучиться магии?"},{"a":"wizard","t":"У учителя припасено еще несколько трюков!"},{"a":"lilu","t":"О! Как насчет полиморфии? Я жажду узнать об этом!"}]}]},{"id":"polonia","name":"Полония","chapters":[{"id":"polonia_01","i":1,"title":"Прославленный cухопутник","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Сухопутники!"},{"a":"polonia","t":"Мечтали когда-нибудь о разудалых приключениях и пиратстве на морских просторах?"},{"a":"polonia","t":"Я, капитан Полония Дель Монте, нанимаю команду для своего корабля!"},{"a":"polonia","t":"Я дочь легендарного пирата Баросса Дель Монте и могу обещать вам добычу и приключения!"},{"a":"argon","t":"Капитан Полония, верно?"},{"a":"polonia","t":"Ага. Стало интересно? Жеребец вроде тебя пришелся бы весьма кстати."},{"a":"argon","t":"Ж-жеребец?!"},{"a":"argon","t":"Э-э, не совсем! Я Аргон, учусь на рыцаря!"},{"a":"argon","t":"Пиратство незаконно, поэтому... пожалуйста, сдавайтесь и уходите с миром!"},{"a":"polonia","t":"Три тысячи чертей! Проклятый рыцарь..."},{"a":"polonia","t":"Э-э, видишь ли, я законный пират, как этот ваш... сухопутник Робин Гуд."},{"a":"polonia","t":"...Я забираю у богатых и отдаю бедным!"},{"a":"argon","t":"О! Это довольно благородно. Вопросов нет, продолжайте!"},{"a":"polonia","t":"...Фух."},{"a":"tavern","t":"Сегодня тоже не везет, да?"},{"a":"polonia","t":"А-а, жизнь в открытом море — штука сложная."}]},{"id":"polonia_02","i":2,"title":"История Дель Монте","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"tavern","t":"Полония, сегодня вербовать больше никого не будешь?"},{"a":"polonia","t":"Это бесполезно. Я никудышный капитан пиратов и не достойна носить имя Дель Монте..."},{"a":"tavern","t":"Этот Баросс Дель Монте... он твой дедушка, да?"},{"a":"polonia","t":"Ага! Легенда из легенд! Сейчас для нас, пиратов, настали тяжелые времена..."},{"a":"polonia","t":"На всех торговых судах в наши дни есть причудливые магические средства обнаружения, что позволяют легко избежать нас, морских волков."},{"a":"polonia","t":"Но Баросс был не таков! Несмотря на магию, он атаковал из тумана незамеченным!"},{"a":"polonia","t":"Забирал все ценные вещи, оставляя жертвам только свой раскатистый фирменный смех..."},{"a":"polonia","t":"Даже когда все остальные пираты ушли на покой, он продолжал вселять ужас на море еще десятки лет!"},{"a":"tavern","t":"Вполне достойное наследие!"},{"a":"polonia","t":"Ага! И после каждого путешествия он всегда находил время навестить внучку и поведать ей о своих приключениях..."},{"a":"polonia","t":"«Поднять черный флаг! Огонь из пушек! Все на корм, готовимся грабить!»"},{"a":"tavern","t":"Почему на корм, а не на корму?"},{"a":"polonia","t":"...Р-р-р! Проклятье! Я всего лишь сухопутная крыса в модном костюмчике, которая усердно пытается говорить как настоящий пират."},{"a":"polonia","t":"И что это за пират без корабля?!"},{"a":"tavern","t":"Без корабля? Может быть, с этого и следует начать."},{"a":"polonia","t":"А?"},{"a":"tavern","t":"Капитан без корабля нескоро наберет команду!"},{"a":"tavern","t":"Но если тебе нужен корабль, думаю, я знаю, кто тебе может помочь."},{"a":"polonia","t":"...Правда?"},{"a":"polonia","t":"Ну то есть, клянусь Веселым Роджером, спасибо тебе, трактирщица! Капитан Полония в долгу перед тобой!"},{"a":"tavern","t":"Поверь мне, я очень на это надеюсь."}]},{"id":"polonia_03","i":3,"title":"Дело корабела","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"carpenter","t":"Ты хочешь, чтобы я построил целый корабль?!"},{"a":"polonia","t":"Ага. Сможешь?"},{"a":"carpenter","t":"Еще бы! Это будет мой шедевр! Дай-ка взглянуть на чертежи."},{"a":"carpenter","t":"Хм... они довольно сложные. Что это за каракули?"},{"a":"polonia","t":"Мой почерк. Я не умею читать."},{"a":"carpenter","t":"А, тогда понятно. Однако этих чертежей более чем достаточно."},{"a":"polonia","t":"Йо-хо-хо! Это будет величайший корабль из тех, что бороздили моря после Баросса и его «Бонавентуры»!"},{"a":"carpenter","t":"Но тут возникает вопрос финансов. Ты точно можешь себе это позволить?"},{"a":"polonia","t":"Дублоны не проблема. Построй корабль, а я принесу тебе добычу."}]},{"id":"polonia_a","i":3,"title":"Без задних ног","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"polonia","t":"Привет, милая девушка. Ты ведь целительница, да?"},{"a":"priest","t":"О да! Я Фрейя, жрица этого хра..."},{"a":"polonia","t":"Отруби мне ногу."},{"a":"priest","t":"Что-что?"},{"a":"polonia","t":"Я попросила отрубить мне ногу."},{"a":"priest","t":"Святые небеса, нет! Как можно такое просить?"},{"a":"polonia","t":"Я пират! У капитана пиратов должна быть деревянная нога, черт возьми!"},{"a":"polonia","t":"Отруби мне ногу и залатай ее своей чудной магией!"},{"a":"priest","t":"Я отказываюсь. Я поклялась Богине никогда не причинять вред человеческому существу."},{"a":"polonia","t":"Ох уж эти бесполезные сухопутники! Ладно! Тогда и дублонов от меня не получишь!"},{"a":"priest","t":"...Какая странная девушка."}]},{"id":"polonia_04","i":4,"title":"Капитанская доля","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"А-а, у этих йети полно добычи! Я мигом заплачу за свой корабль!"},{"a":"leather","t":"Так, дорогуша, я здесь. Чего надобно?"},{"a":"polonia","t":"Для тебя я капитан Полония, салага!"},{"a":"leather","t":"Конечно, дорогуша капитан. Чего ты хочешь, чтобы я сделал?"},{"a":"polonia","t":"Ты притащил свою телегу. Я обчищу этих йети до нитки, а ты повезешь добычу."},{"a":"leather","t":"Дорогуша капитан, ты будешь грабить этих прекрасных мохнатиков?"},{"a":"polonia","t":"Ага. По какой-то причине у них всегда полно ценных вещей вроде боевых молотов и составных луков."},{"a":"leather","t":"А что насчет шкур, дорогуша капитан? Отдашь их мне?"},{"a":"polonia","t":"Знай свое место, салага! Пираты грабят, а не убивают!"},{"a":"leather","t":"А вот это зря."},{"a":"polonia","t":"Совсем нет. Если оставляешь жертв живыми, они насобирают еще добычи, которую можно забрать позже. Это экономически выгодно!"},{"a":"polonia","t":"Продолжай работать, салага, если хочешь свою долю!"},{"a":"leather","t":"Да-да, дорогуша капитан."}]},{"id":"polonia_05","i":5,"title":"Спуск на воду","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"carpenter","t":"Узри же шедевральную работу всей моей жизни!"},{"a":"polonia","t":"Он... красивый. Прямо на слезу прошибло."},{"a":"carpenter","t":"Правда? Мне пришлось кое-что убрать, например пушки в вороньем гнезде. Странно было настаивать на их размещении там..."},{"a":"carpenter","t":"Но, думаю, все получилось вполне хорошо, верно ведь?"},{"a":"polonia","t":"Верно, дружище. Вот тебе дублон, заслужил."},{"a":"carpenter","t":"Конечно, заслужил! Но хочу сказать кое-что напоследок. Я хоть и мастер-плотник, но в тканях не разбираюсь."},{"a":"carpenter","t":"...А без паруса твой корабль из порта в скором времени не выберется!"},{"a":"polonia","t":"Твой капитан и так может тобой гордиться, дружище. А парус у меня есть."},{"a":"carpenter","t":"Ух ты! Вот это произведение искусства! Еще и магический! Откуда он?"},{"a":"polonia","t":"Достался от дедушки Баросса. Тот самый, что был на его корабле «Бонавентуре»!"},{"a":"carpenter","t":"Понятно! Замечательный завершающий штрих для этого судна!"},{"a":"carpenter","t":"Что ж, капитан Полония, «Великолепный Аллан» твой!"},{"a":"polonia","t":"Ты назвал его «Великолепный Аллан»? Погоди-ка..."},{"a":"polonia","t":"Фигура на носу... это же ты! Еще и голый!"},{"a":"carpenter","t":"Ха-ха! Думаю, лучшей фигуры для такого совершенного корабля не сыскать!"}]},{"id":"polonia_b","i":5,"title":"Со всех ног","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"polonia","t":"Эй, привет!"},{"a":"wood","t":"А?"},{"a":"polonia","t":"Отруби мне ногу."},{"a":"wood","t":"Конечно."},{"a":"polonia","t":"Я сказала... Постой, ты не против?"},{"a":"wood","t":"Нет, конечно. Только держи ногу вот так. Сейчас мой старый топор все сделает."},{"a":"polonia","t":"Эй, погоди!"},{"a":"wood","t":"Красиво не будет, но ты ведь крутая девчонка, верно?"},{"a":"wood","t":"Не забудь хорошо наложить жгут. Мы же не хотим, чтобы ты истекла кровью."},{"a":"polonia","t":"Стой, дружище! Не торопись!"},{"a":"polonia","t":"Я... Мой корабль скоро уплывает! М-мне надо на него успеть! До встречи, дружище!"},{"a":"wood","t":"...Ха! Люди. Никогда не дают скучать."}]},{"id":"polonia_06","i":6,"title":"Наследие в море","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Мой король, у меня ужасная новость."},{"a":"king","t":"О нет! Неужели в Потерянном городе золота закончилось золото?!"},{"a":"sia","t":"Нет, к счастью, не такие ужасная."},{"a":"sia","t":"Однако, боюсь, назойливый пират грабит ваш личный торговый флот."},{"a":"sia","t":"...Кража оценивается более чем в 100 триллионов золотых."},{"a":"king","t":"Клянусь богиней! А как же современная система магического обнаружения пиратов у моего флота?"},{"a":"sia","t":"Похоже, совершенно неэффективна. Как и сам великий Баросс, этот корабль ускользает даже от нашей лучшей магии..."},{"a":"sia","t":"...Отбирая у вас золото, прежде чем ускользнуть в море."},{"a":"king","t":"Какое неслыханное варварство! А что с командой?"},{"a":"sia","t":"Их щадят, мой король. Если они не оказывают сопротивления."},{"a":"king","t":"Тогда золото — это небольшая цена. Я буду питаться крестьянской пищей, пока не верну свое состояние!"},{"a":"king","t":"...Сколько это займет?"},{"a":"sia","t":"Приблизительно два дня, мой король."},{"a":"king","t":"Воистину темные времена..."}]},{"id":"polonia_07","i":7,"title":"Отпуск на берегу","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Капитан Полония на берегу! Выпивка за мой счет!"},{"a":"tavern","t":"Полония! Или мне следует обращаться... капитан Полония? Полагаю, «дела» у вас идут хорошо?"},{"a":"polonia","t":"Можешь поклясться своими сухопутными прелестями, что так и есть! В этих морях можно много чего награбить!"},{"a":"polonia","t":"Где бы ни был мой корабль, дедушкины паруса всегда ловят ветер, такая вот невиданная вещь!"},{"a":"tavern","t":"Уверена, Баросс бы гордился. И что вы намерены делать с этим... нечестно нажитым добром?"},{"a":"polonia","t":"Как всякий хороший пират, я его закопала то там, то сям вместе со своей командой."},{"a":"tavern","t":"О-о-о! Карты сокровищ! Какая прелесть!"},{"a":"polonia","t":"Да, мы, пираты, такие. Сберегаем кое-что на случай холодной зимы, будто сухопутные белки."},{"a":"tavern","t":"А остальное?"},{"a":"polonia","t":"Я отдала его милой девушке в храме."},{"a":"tavern","t":"Пожертвование в сиротский приют? Я и не думала, что вы филантроп."},{"a":"polonia","t":"Филан-кто?"},{"a":"tavern","t":"Неважно. Что вам принести, капитан?"},{"a":"polonia","t":"Мое любимое, варево морского волка! И для любого сухопутника, считающего, что его не вырвет..."},{"a":"polonia","t":"Следующая кружка за мой счет! Бароссы снова в море! Йо-хо-хо!"}]},{"id":"polonia_08","i":8,"title":"Шепоты из прошлого","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Русал, готов к следующему заплыву?"},{"a":"baker","t":"Всегда готов, капитан! Хотя, надо отметить..."},{"a":"baker","t":"Хоть мне и нравится помогать исследовать дно морское, пиратство меня не привлекает!"},{"a":"polonia","t":"Дружище, не парься. У нас особое задание. Твой капитан расширяет горизонты."},{"a":"polonia","t":"Сегодня без пиратства. Но если повезет, мы найдем затонувший корабль и поживимся чем-нибудь! Хо-хо-хо!"},{"a":"baker","t":"М-м, капитан? А что это за корабль по курсу?"},{"a":"polonia","t":"Арр! Спокойствие, рыбешка! Это та самая «Бонавентура»! Корабль дедушки."},{"a":"baker","t":"Точно? Какой-то он потрепанный..."},{"a":"polonia","t":"...Разрази меня Нептун! Та самая «Бонавентура»! Н-но... это невозможно! Мой дедушка давно мертв!"},{"a":"polonia","t":"Друзья! Смена курса! НАМ НУЖЕН ЭТОТ КОРАБЛЬ!"}]},{"id":"polonia_09","i":9,"title":"Легенда на плаву","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"baker","t":"...Скажи мне кто, что я взойду на борт древней развалюхи, ха!"},{"a":"polonia","t":"Смотри под ноги, матрос! Корабль в плачевном состоянии."},{"a":"baker","t":"Если уж честно, то я бы лучше поплавал. А что мы вообще забыли на этой посудине?"},{"a":"polonia","t":"В смысле «Что»? Это же «Бонавентура» Баросса!"},{"a":"polonia","t":"Нужно выяснить, что тут стряслось. Эта развалюха вообще не должна быть на ходу."},{"a":"baker","t":"...Корабль-призрак, не иначе."},{"a":"polonia","t":"Меня таким не напугаешь. Призраков не существует!"},{"a":"baker","t":"А как же Зо..."},{"a":"polonia","t":"Закройся, дружище! Поищу подсказки."},{"a":"baker","t":"Этот бортовой журнал пугает..."},{"a":"polonia","t":"Ага! Записи капитана!"},{"a":"baker","t":"Как будто в душу смотрит...да?"},{"a":"polonia","t":"Так, ты пойдешь со мной, журнал. Поищите еще что-нибудь полезное."},{"a":"polonia","t":"...Эй, прекрати трогать мои волосы!"},{"a":"baker","t":"Капитан, я здесь."},{"a":"polonia","t":"...АААААРГХ! Прочь с корабля!"}]},{"id":"polonia_10","i":10,"title":"Наследие пирата","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Ваш капитан вернулся! Поднять паруса, мы отчаливаем!"},{"a":"baker","t":"Капитан, смотрите! «Бонавентура» тонет!"},{"a":"polonia","t":"Вот холера! Как это возможно? После всего, что было?! Неужто журнал держал ее на плаву?"},{"a":"baker","t":"...Возможно, песенка ее спета."},{"a":"polonia","t":"Баросс, морской пес, откуда же ты знал?"},{"a":"baker","t":"Полония, что там с записями?"},{"a":"polonia","t":"Ах да, дай-ка взгляну..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"...Русал, дело есть к тебе."},{"a":"baker","t":"Ага, дай-ка прочту."},{"a":"baker","t":"Хм-м, похоже на инструкции, как найти что-то под водой."},{"a":"polonia","t":"Затонувший храм? Это уже не новость."},{"a":"baker","t":"Нет, это совсем другое место... Может, Потерянный город золота?"},{"a":"baker","t":"Потерянный город золота не уходил под воду..."},{"a":"polonia","t":"То есть это не выдумки? Место реально существовало?"},{"a":"polonia","t":"Русал, ты можешь плыть. Это судьба."},{"a":"polonia","t":"Если все слухи окажутся правдой, ты не пожалеешь о путешествии."}]},{"id":"polonia_11","i":11,"title":"Затонувший город золота","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"baker","t":"Фух! Мы на месте! Вы как там, капитан?"},{"a":"polonia","t":"*кашель* *Ай*..."},{"a":"polonia","t":"Кхех!.. вот это у тебя... быстрые ноги... для русала-то!"},{"a":"baker","t":"И это хорошо! Этот вход находится так глубоко под водой, не думаю, что хоть кто-то смог бы добраться сюда."},{"a":"polonia","t":"Именно! Я чуть не утонула! Ноги моей там больше не будет!"},{"a":"baker","t":"Храни нас богиня! Полония, смотри!"},{"a":"polonia","t":"Борода Балянуса! Затонувший город золота..."},{"a":"polonia","t":"Это место... Никогда ничего подобного не видела!.."},{"a":"baker","t":"Сколько здесь богатств! Золото, жемчуг... Потерянный город золота просто жалкая пародия на это!"},{"a":"polonia","t":"Всю свою жизнь мой дед искал это место."},{"a":"baker","t":"В конце концов, он ничего не смог унести с собой на сушу, поэтому оставил все это своей любимой внучке."},{"a":"polonia","t":"*всхлип* Глаза наполняются слезами..."},{"a":"baker","t":"Ваш нужна минутка, капитан?"},{"a":"polonia","t":"Шутишь что ли? Там есть чем поживиться! И ты становишься первым помощником капитана! Готовность к заплыву!"},{"a":"baker","t":"Я потащу добычу И пирата? Надо размяться!"}]},{"id":"polonia_epilogue","i":12,"title":"Эпилог","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Хм..."},{"a":"baker","t":"Полония, у нас еще заплыв намечается?"},{"a":"polonia","t":"Не, дружище! У меня большая проблема."},{"a":"polonia","t":"У меня целая куча денег! Уже и пляжей не осталось, где это все закапывать."},{"a":"baker","t":"Ух, меня будоражит причитающаяся мне доля."},{"a":"baker","t":"О, кстати!"},{"a":"baker","t":"Я тут поплавал вокруг затонувшей «Бонавентуры»..."},{"a":"baker","t":"Там мало что осталось, но вот кое-что. Что-то узнаешь?"},{"a":"polonia","t":"Старпом капитана! Это же повязка Баросса!"},{"a":"polonia","t":"Хо-хо-хо! Как я счастлива! Готова тебя затискать!"},{"a":"baker","t":"Рад служить, капитан! Уверен, что таково было его желание."},{"a":"polonia","t":"...Знаешь что, с меня хватит этого подводного мародерства!"},{"a":"polonia","t":"Море — дом пирата, а не золотая жила! И неважно, сколько там добычи."},{"a":"polonia","t":"Как внучка великого Баросса, я дарю тебе Затонувший город золота и все оставшиеся в нем трофеи."},{"a":"polonia","t":"Спасибо за помощь, старпом! Если когда-нибудь передумаешь насчет пиратства, добро пожаловать к нам."},{"a":"baker","t":"Спасибо, капитан! Я пронесу в сердце воспоминания о наших приключениях!"},{"a":"baker","t":"...Наверно, по возвращении мне стоит переговорить с Туту Мано."}]}]},{"id":"king","name":"Рейнгольд","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Король Рейнгольд..."},{"a":"king","t":"Ох... Похоже, мои служебные обязанности меня настигли!"},{"a":"sia","t":"Точнее сказать, завалили. Сановники ждут."},{"a":"king","t":"Прощай, лавочных дел мастер! Я еще вернусь!"},{"a":"sia","t":"Нет, это вряд ли."}]},{"id":"king_01","i":1,"title":"Королевский суд","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"king","t":"Королевский суд открыт! Просители, заходите!"},{"a":"rudo","t":"Пф."},{"a":"king","t":"Что может сделать королевство Рейнгольда для своих подданных, большой... человек-медведь?"},{"a":"rudo","t":"Я думаю, что нужно запретить всю магию и выгнать заклинателей."},{"a":"king","t":"О... это... э-э..."},{"a":"king","t":"Мы... учтем ваше предложение! Следующий!"},{"a":"herbs","t":"Приве-е-ет! Думаю, мы должны объявить каждый день ДНЕМ ПИНЬЯТЫ!"},{"a":"king","t":"Какая великолепная идея! Мы даже могли бы..."},{"a":"sia","t":"..."},{"a":"king","t":"...потратить немало времени на обсуждение этого вопроса! Спасибо, что пришли!"},{"a":"king","t":"Сиа, сколько еще просителей сегодня?"},{"a":"sia","t":"Пятьдесят пять, мой король."},{"a":"king","t":"Ох!"}]},{"id":"king_02","i":2,"title":"Золотое сердце глупца","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"donovan","t":"Простите, это место занято?"},{"a":"sia","t":"Пришел испортить мне выходной, Донован?"},{"a":"donovan","t":"Обижаешь, Сиа. Я просто общаюсь с таким же гражданином империи, как я."},{"a":"donovan","t":"Как поживает наш глупый король в эти дни?"},{"a":"sia","t":"Донован, ты теряешь свой шпионский нюх. Рейнхольд далеко не такой глупец, каким ты его считаешь."},{"a":"sia","t":"Хотя он и улыбается, он многим жертвует ради своего народа."},{"a":"sia","t":"Этому мог бы поучиться император... НАШ император."},{"a":"sia","t":"До сих пор моя роль заключалась в том, чтобы не дать ему погубить себя во имя своего народа."},{"a":"donovan","t":"Правда? Очаровательно."},{"a":"sia","t":"Да, он глупец с золотым сердцем. Но ты недооцениваешь его на свой страх и риск."}]},{"id":"king_03","i":3,"title":"Внеурочное время короля","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"king","t":"Ого! Эта груда докладов меньше не становится?"},{"a":"sia","t":"Похоже, нас ждет еще одна бессонная ночка."},{"a":"king","t":"Спасибо, что помогаешь мне в этом, дорогая Сиа!"},{"a":"sia","t":"Ничего страшного, мой король. Переходим к следующему докладу..."},{"a":"sia","t":"Фермеры из Саутбурга недоплатили налоги, сославшись на плохой урожай."},{"a":"sia","t":"Кажется, это уже во второй раз..."},{"a":"king","t":"Отправь нескольких моих придворных чародеев провести расследование. Возможно, на их земли наводили порчу."},{"a":"sia","t":"Весьма великодушное решение."},{"a":"king","t":"И снова прости им налоги. Этого хотел бы мой отец!"},{"a":"sia","t":"Хорошо. Я считаю, что король Кинан поступил бы так же."},{"a":"king","t":"Корона, которую он оставил после себя, действительно тяжела..."},{"a":"king","t":"Что говорится в следующем докладе?"},{"a":"sia","t":"Здесь говорится о напряженности на границе с соседней империей..."}]},{"id":"king_04","i":4,"title":"Прыжки в тени","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Мой король..."},{"a":"king","t":"Ай!"},{"a":"king","t":"П-пожалуйста, объявляй о своем присутствии заранее, если хочешь подкрасться ко мне сзади!"},{"a":"sia","t":"Нападение той ниндзя не дает вам покоя, да?"},{"a":"king","t":"Конечно! Я был на волосок от смерти!"},{"a":"sia","t":"Мне удвоить стражу?"},{"a":"king","t":"В этом... нет необходимости. Но, пожалуйста, в будущем не ходи так тихо!"},{"a":"sia","t":"Как пожелаете, мой король."},{"a":"hemma","t":"Ах, как хорошо быть дома... Что?"},{"a":"king","t":"А-а-а!!! Н-ниндзя?!"},{"a":"hemma","t":"Прошу прощения. Похоже, мы промахнулись."},{"a":"hemma","t":"Теневая транслокация иногда бывает несколько неточной."},{"a":"king","t":"П-пожалуйста, воздержитесь от ТЕНЕВОЙ ТЕЛЕПОРТАЦИИ в моем тронном зале!"},{"a":"sia","t":"К-король Рейнгольд? Вы в порядке?"},{"a":"king","t":"Да! Пожалуйста, проведи эту... жуткую посетительницу к выходу."},{"a":"sia","t":"Хорошо. Я позабочусь о том, чтобы в будущем замок был надежно защищен от подобных вторжений."},{"a":"hemma","t":"Мы нашли довольно занимательную путевую точку, поэтому еще вернемся."},{"a":"king","t":"Надеюсь, что нет!"}]}]},{"id":"rudo","name":"Рудо","chapters":[{"id":"rudo_01","i":1,"title":"Человек-гора","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Бр-р-р... Моя одежда не подходит для такой холодины! Напомни, почему мы здесь?"},{"a":"lilu","t":"У местных кристаллов есть чудесные свойства! Гримар сказал мне..."},{"a":"argon","t":"Постой, Лилу! Смотри! Там какой-то человек дерется с йети!"},{"a":"lilu","t":"Человек? Да он огромный, как гора!"},{"a":"lilu","t":"И он... побеждает йети?"},{"a":"rudo","t":"Уф... Это десятый."},{"a":"argon","t":"Впечатляющий бой, сэр! Вы были великолепны!"},{"a":"rudo","t":"А?"},{"a":"lilu","t":"Господин... вы ранены! Позвольте мне вас исцелить!"},{"a":"lilu","t":"<c1>Исце</c1>..."},{"a":"rudo","t":"НАЗАД!"},{"a":"rudo","t":"Я в порядке. Само заживет."},{"a":"rudo","t":"Малыши не должны шляться в таких местах. Идите домой."},{"a":"argon","t":"Ого, он что, так ненавидит магию?"},{"a":"lilu","t":"Нет. В его глазах я увидела... страх."}]},{"id":"rudo_02","i":2,"title":"Уведомление о выселении","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"elderowen","t":"Боюсь, я не понимаю..."},{"a":"rudo","t":"Ха! Тогда я скажу проще, чтобы до твоих старых мозгов дошло!"},{"a":"rudo","t":"Чародей, что живет в этом городе, — буйный сумасшедший, и его следует вышвырнуть ради безопасности всех нас."},{"a":"elderowen","t":"Ой-ой... какие резкие слова..."},{"a":"rudo","t":"Буквально вчера он сказал мне приглядывать за Тимофеем..."},{"a":"rudo","t":"...Мол, Тим бредит, ничего не соображает и должен находиться под наблюдением."},{"a":"rudo","t":"Но он же и есть Тимофей!"},{"a":"elderowen","t":"Хм, да, понятно."},{"a":"elderowen","t":"Несмотря на его... «состояние», Тимофей Гримар — неотъемлемая часть этого города."},{"a":"elderowen","t":"Он столь же полезен, как и безобиден. Я не вижу причин для тревоги."},{"a":"lilu","t":"Мастера Гримара выгоняют? Что за дела?!"},{"a":"rudo","t":"Не лезь в это, девчонка."},{"a":"lilu","t":"Нет! Мастер Гримар — могучий чародей, но он никогда бы не причинил вреда никому!"},{"a":"rudo","t":"Ха! Ладно! Если этот город взлетит на воздух, не говорите, что я вас не предупреждал."},{"a":"elderowen","t":"Вот ведь возмутитель спокойствия."},{"a":"lilu","t":"Лучше я буду за ним присматривать..."}]},{"id":"rudo_03","i":3,"title":"Искророжденные","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"priest","t":"Простите... Что это вы ворчите?"},{"a":"rudo","t":"Проклятье. Почему в этом городе так много этих проклятых заклинателей?.."},{"a":"priest","t":"А, господин Рудо, я полагаю."},{"a":"rudo","t":"Не пытайся подружиться со мной, чародейка."},{"a":"priest","t":"Я жрица Богини, мои способности не такие, как у чародеев."},{"a":"priest","t":"Я поклялась, что посвящу жизнь исцелению и защите других."},{"a":"rudo","t":"Я на это не куплюсь. Все вы, искророжденные, одинаковые."},{"a":"priest","t":"Вам известно об Искре?.."},{"a":"rudo","t":"Пф. Забудь, что я что-то сказал. Я ухожу отсюда."},{"a":"priest","t":"...Ты слышала, Лилу?"},{"a":"lilu","t":"Ага, все до единого слова!"},{"a":"priest","t":"Ты помнишь мои уроки об Искре?"},{"a":"lilu","t":"Конечно! Только рожденные с Искрой могут контролировать и создавать магические заклинания."},{"a":"lilu","t":"Однако это явление, как правило, неизвестно широкой общественности."},{"a":"priest","t":"Все верно! Чего и следовало ожидать от моей самой умной ученицы!"},{"a":"priest","t":"Хотя тут возникает вопрос... Откуда он об этом знает?.."},{"a":"lilu","t":"Хм... Ты думаешь, что..."}]},{"id":"rudo_04","i":4,"title":"Круши и хватай","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"polonia","t":"Йо-хо-хо! Капитан Полония в этот раз сорвала куш!"},{"a":"polonia","t":"Целая королевская гробница, готовая к разграблению!"},{"a":"rudo","t":"Потише, морячка. Я занят."},{"a":"polonia","t":"Но не тут-то было... ведь заросший берсерк РАЗНЕС НА КУСКИ ВСЮ ДОБЫЧУ!"},{"a":"polonia","t":"Ты чего творишь, дружище, чтоб тебя акулы сожрали? Это же стоит кучу дублонов!"},{"a":"rudo","t":"Древние вещи."},{"a":"rudo","t":"Магические."},{"a":"rudo","t":"И, вероятно, проклятые."},{"a":"rudo","t":"Я разношу все вдребезги, чтобы избавить кого-то от неприятностей."},{"a":"rudo","t":"Если этот город слишком глуп, чтобы видеть проблему, то я позабочусь об этом сам!"},{"a":"polonia","t":"Эй, дружище! Этот посох, похоже, РЕАЛЬНО ценный. Ты же не собираешься..."},{"a":"rudo","t":"Пф."},{"a":"rudo","t":"Ай!"},{"a":"polonia","t":"Клянусь кракеном! Ну не надо ломать об колено!"},{"a":"polonia","t":"Хотя, похоже, ломательным оказался сам посох. На нем ни царапины!"},{"a":"polonia","t":"Как твоя нога, дружище?"},{"a":"rudo","t":"Нормально. Но этот посох крепче, чем кажется."},{"a":"rudo","t":"И по какой-то причине я не могу его бросить. Будто он... приклеился к руке."},{"a":"polonia","t":"Я не корабельный хирург, но, видать, тебе прилетело хорошенькое проклятие, дружище."},{"a":"polonia","t":"Не мешало бы тебе у доктора провериться."},{"a":"rudo","t":"Конечно, это проклятая магия. Это ВСЕГДА она."},{"a":"rudo","t":"Ладно. Я ухожу. Можешь доломать все остальное."},{"a":"polonia","t":"Да-да, дружище!"},{"a":"polonia","t":"Хотя тут скорее взлом с проникновением, ведь пират отправляется грабить..."}]},{"id":"rudo_a","i":4,"title":"Жесткая любовь","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"herbs","t":"Горза!"},{"a":"gems","t":"Горза!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Привет, Джунипер. И Мэйли! Как дела?"},{"a":"herbs","t":"Мы с Мэйли разговаривали о ее будущем прекрасном принце..."},{"a":"gems","t":"Ой, я жду не дождусь!"},{"a":"herbs","t":"И у нас возник вопрос... а как ТЫ познакомилась со своим?"},{"a":"wood","t":"С этим большим и тупым олухом Рудо? Ха!"},{"a":"wood","t":"Может быть, по нему и не скажешь, но этот мужчина умеет разговаривать с женщинами."},{"a":"wood","t":"Дайте-ка подумать... Вот как все было..."},{"a":"rudo","t":"Выпью-как на посошок..."},{"a":"tavern","t":"Рудо... А ты никогда не думал о том, чтобы завести семью?"},{"a":"rudo","t":"Не лезь не в свое дело, Найя. Нет у меня на это времени."},{"a":"tavern","t":"Любовь наносит удар, когда меньше всего этого ожидаешь! Женщина твоей мечты может войти сюда в любую минуту..."},{"a":"rudo","t":"Вот еще! Мне нужна женщина, которая сможет завалить меня в борцовском поединке на землю."},{"a":"wood","t":"Это вызов, здоровяк?"},{"a":"rudo","t":"А ты проверь, зубастая!"},{"a":"tavern","t":"Горза, пожалуйста, опусти стул..."},{"a":"wood","t":"Как тебе такое, баранья башка? Еще хочешь?"},{"a":"rudo","t":"РА-А-А-А-А!!!"},{"a":"wood","t":"Ого!"},{"a":"wood","t":"А через неделю мы поженились. Такой кровавой свадьбы я никогда не видела."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"Н-наверное, нам стоит кого-то другого спросить."}]},{"id":"rudo_05","i":5,"title":"Проклятия и вспышки гнева","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Как это, не можешь разбить?!"},{"a":"master","t":"Я лишь хотела сказать, мой яростный друг, что я не могу разбить эту реликвию."},{"a":"rudo","t":"Какая тогда польза от адамантинового молота, если он не может разбить этот ничтожный посох?!"},{"a":"master","t":"Ну, не мало, конечно... Чувствуется зло!"},{"a":"master","t":"В любом случае здесь явно замешано что-то еще, вероятно, магия..."},{"a":"rudo","t":"КОНЕЧНО, магия."},{"a":"rudo","t":"Вечно эта проклятая магия."},{"a":"master","t":"Похоже, тебе это и так было известно! Почему бы тогда не обратиться к тому, кто разбирается в таких вещах, а не ко мне?"},{"a":"rudo","t":"Магам верить нельзя... Вообще."},{"a":"master","t":"Ну, вряд ли у тебя здесь есть выбор, сынок."},{"a":"master","t":"Кроме того, как можно было не доверять милой Лилу? Она же прелесть!"},{"a":"rudo","t":"Она же маг, да? Значит, она такая же, как и все остальные."},{"a":"rudo","t":"Опасная. Злобная. МЕРЗКАЯ."},{"a":"master","t":"Ну, она, вероятно, единственная, кто сможет помочь, если ты хочешь хоть когда-то избавиться от этого посоха."},{"a":"rudo","t":"Проклятье..."}]},{"id":"rudo_06","i":6,"title":"Чародей поневоле","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Привет, Найя! Как обычно."},{"a":"tavern","t":"Прости, Рудо, с оружием нельзя. Ты знаешь правила."},{"a":"rudo","t":"А-а, это? Это трость."},{"a":"tavern","t":"Ага, конечно! Волшебный посох я везде узнаю!"},{"a":"rudo","t":"Пф-ф. Ладно. Видишь? Сила проклятия. Не могу отцепить его."},{"a":"tavern","t":"Ох! Думаю, в таком случае, мы можем сделать исключение. Только для тебя!"},{"a":"rudo","t":"Пф. Спасибо!"},{"a":"tavern","t":"И как будешь выходить из ситуации?"},{"a":"rudo","t":"Не переживай. Я просто буду жить дальше."},{"a":"tavern","t":"Точно? Из-за него ты капризничаешь. Ну-у, еще сильнее — если это вообще возможно."},{"a":"tavern","t":"Да и глядя на тебя, складывается впечатление, что ты какой-то маг."},{"a":"rudo","t":"...Правда? Дурацкий маг?"},{"a":"tavern","t":"Тебе только шапки не хватает! И изысканных манер!"},{"a":"rudo","t":"...Наверное так и есть. Надо что-то решать. Увидимся!"},{"a":"tavern","t":"Хорошего дня! Запишу это на твой счет!"}]},{"id":"rudo_07","i":7,"title":"Проблеск травмы","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Жаль, что так случилось. Говорят, твоя помощь может быть полезна. С проклятием."},{"a":"lilu","t":"Посох, да? Ну и жуть!"},{"a":"lilu","t":"Мне не доводилось снимать проклятия, но теоретически... Должно получиться."},{"a":"lilu","t":"Точно? Сомнений нет? Чувствую напряженность."},{"a":"rudo","t":"Да..."},{"a":"lilu","t":"Ок! Надо сосредоточиться..."},{"a":"lilu","t":"Чувствую проклятие... оно окружило тебя коконом."},{"a":"lilu","t":"Потерпи, нужно больше деталей..."},{"a":"rudo","t":"Аргх!"},{"a":"lilu","t":"А-ах!"},{"a":"lilu","t":"Кажется, еще секунда и от тебя прилетела бы ОПЛЕУХА!"},{"a":"rudo","t":"Прости... Я не специально."},{"a":"lilu","t":"Не думаю, что сработает. Мне нужно сосредоточиться, понимаешь?"},{"a":"rudo","t":"Да, прости. Поищу что-то еще."},{"a":"lilu","t":"Может, попросить Хворь? Она может уметь то, чего не умею я."},{"a":"rudo","t":"Хворь? Гм-м. Попробую."},{"a":"lilu","t":"Помни про манеры! У нее... особые обстоятельства, о которых стоит знать..."}]},{"id":"rudo_08","i":8,"title":"Проклятие на двоих","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Госпожа Хворь, есть минутка?"},{"a":"malady","t":"(О нет, Лилу о нем предупреждала...)"},{"a":"malady","t":"М-м-м... извините. Не думаю..."},{"a":"rudo","t":"Простите, пугать вас не входило в мои планы. Думаю, вдруг вам что-то известно про посох."},{"a":"malady","t":"Вдруг вы... ну-у... магию люто ненавидите?"},{"a":"rudo","t":"Больше всего на свете."},{"a":"rudo","t":"Вас ведь прокляли, да? Как и меня."},{"a":"rudo","t":"Вы не выбирали магию. В этом нет вашей вины."},{"a":"malady","t":"В таком случае... попробую заговорить с посохом."},{"a":"malady","t":"..."},{"a":"malady","t":"Что-то в нем есть от паразитов. Он питается вашей искрой."},{"a":"rudo","t":"Разве не умно?"},{"a":"malady","t":"Да-а... вроде того."},{"a":"malady","t":"Ваша искра удивительно сильная. Может, уйдут годы, но..."},{"a":"malady","t":"...Вдруг мне удастся расколдовать вас?.."},{"a":"rudo","t":"Пф. Правда, веры в это маловато."},{"a":"rudo","t":"То есть, ему просто нужен источник магии, так?"},{"a":"malady","t":"Гм-м... да. Вроде того."},{"a":"malady","t":"Пожалуйста... На мне и так висит проклятие..."},{"a":"rudo","t":"Ха! Мисс, а так и не скажешь, ха!"},{"a":"rudo","t":"Спасибо за помощь! Кажется, у меня есть идея..."}]},{"id":"rudo_09","i":9,"title":"Прошлое солдата","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"malady","t":"Гм-м... Можно войти?"},{"a":"veteran","t":"А-а. Вы та самая Медуза."},{"a":"veteran","t":"Заходите, ходячая неприятность. Стульев вашего размера, боюсь, нет."},{"a":"malady","t":"Ничего... спасибо! Хочу расспросить вас об одном мужчине. О Рудо."},{"a":"veteran","t":"О громиле? Он же не издевался над вами?"},{"a":"malady","t":"Нет, он был необычайно... добр ко мне."},{"a":"veteran","t":"Точно? Странно. Он ненавидит магию."},{"a":"malady","t":"Поэтому я здесь. Хотела спросить... почему?"},{"a":"veteran","t":"Когда-то давно мы с ним служили в имперской армии. Старые товарищи."},{"a":"veteran","t":"Рудо... «вызвался добровольцем» эксперимента. Того самого, когда солдатам вживляли искру."},{"a":"veteran","t":"Дрянные были дела. После этого он изменился."},{"a":"malady","t":"Как ужасно... "},{"a":"veteran","t":"Ужаснее некуда. Мы унесли оттуда ноги при первой возможности."},{"a":"malady","t":"Но был от этого прок? Я ощутила в нем неимоверно сильную искру..."},{"a":"veteran","t":"Трудно сказать. Ты же видела что с ним. Даже сам император не смог бы заставить его произнести простейшее заклинание."},{"a":"malady","t":"А теперь и вовсе... на нем это отвратительное проклятие... Мы сможем помочь?"},{"a":"veteran","t":"Он сам пришел к тебе, так? Его просьба о помощи — хороший знак! "},{"a":"veteran","t":"Пусть он не самый умный, но парень упорный. Уверен, он что-то да придумает."}]},{"id":"rudo_10","i":10,"title":"Передача права собственности","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"rudo","t":"Так, ладно, ты, кусок дерева! Я тебя порежу!"},{"a":"rudo","t":"Или передам вон тому гиблину!"},{"a":"monster_Forest_Blacksmith","t":"Ай! Пусти!.."},{"a":"rudo","t":"Ты становишься друзьями с этой штуковиной, а мы забываем о случившемся."},{"a":"rudo","t":"А ежели не захочешь..."},{"a":"rudo","t":"Я прыгну в лаву и посмотрим, кто из нас продержится дольше."},{"a":"rudo","t":"Так что? «Водичка» так и манит!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"...Прекрасный выбор. Удачи, гиблин!"},{"a":"monster_Forest_Blacksmith","t":"Аргх! Застряло!"},{"a":"rudo","t":"Гуа-ха-ха-ха! Пока!"}]},{"id":"rudo_epilogue","i":11,"title":"Эпилог","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Рудо! В тот раз..."},{"a":"rudo","t":"Гм-м?"},{"a":"lilu","t":"О! Ты уже без посоха?!"},{"a":"rudo","t":"Ага. Одной проблемой меньше."},{"a":"rudo","t":"...Прости за тот раз. Нервы были на пределе."},{"a":"lilu","t":"...Я прощаю тебя. Но впредь тебе стоит лучше относится к магам."},{"a":"rudo","t":"Ха! Помощь Хвори пришлась весьма кстати. Кто знает, может я и передумаю."},{"a":"lilu","t":"Ей удалось снять проклятие?"},{"a":"rudo","t":"Не совсем. Но благодаря ей мне удалось обрести... руку помощи."},{"a":"rudo","t":"Немного совместной работы не повредит. Гуа-ха-ха-ха!"},{"a":"argon","t":"Эшли, осторожно! Что-то приближается!"},{"a":"ashley","t":"Я готова ко всему! Иди сюда!"},{"a":"monster_Forest_Blacksmith","t":"...Помогите..."},{"a":"argon","t":"А?"},{"a":"ashley","t":"А-а-аа?"}]}]},{"id":"sia","name":"Сиа","chapters":[{"id":"sia_01","i":1,"title":"Первые шаги короля","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"king","t":"Сиа! Я принял решение!"},{"a":"sia","t":"Да, мой король?"},{"a":"king","t":"Сегодня я хочу отправиться за покупками!"},{"a":"sia","t":"Отличная идея, ваше величество."},{"a":"sia","t":"Но я вот смотрю ваше расписание, и сегодня вы, похоже, должны встретиться с чужеземными сановниками..."},{"a":"king","t":"Ох, что за скука! А мы не можем просто отослать их?"},{"a":"sia","t":"Помните, мой король, что, хотя вы и молоды, вы все-таки король. Ваше слово — закон."},{"a":"king","t":"...Ты абсолютно права! Тогда покупки! Сановники могут и подождать!"},{"a":"sia","t":"Ваша решимость достойна восхищения. Мне вас сопровождать?"},{"a":"king","t":"Конечно! Я больше никому не доверяю защиту своей прекрасной особы."}]},{"id":"sia_02","i":2,"title":"Везде свои люди","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"...И поэтому у меня есть причины считать, что жизни нашего короля, возможно, угрожает опасность."},{"a":"elderowen","t":"Ясно. Покушение на жизнь короля выгодно нескольким королевствам-соперникам."},{"a":"elderowen","t":"Подозрительные личности мне не попадались, но, уверен, Найе, хозяйке таврены, известно больше."},{"a":"sia","t":"Спасибо, старейшина. Я признательна вам за мудрость и патриотизм."},{"a":"elderowen","t":"Не стоит благодарности. Я житель этого королевства, и мой долг — заботиться о его процветании."},{"a":"elderowen","t":"Пусть Рейнгольд молод и глуп, но из него получится прекрасный король... со временем."},{"a":"sia","t":"А мой долг — позаботиться о том, чтобы он до этого дожил!"},{"a":"tavern","t":"Так-так, нечасто мы видим у нас в таверне истинную голубую кровь!"},{"a":"sia","t":"Прекрати паясничать, Найя, ты знаешь, кто я."},{"a":"tavern","t":"Конечно! Сиа Леонель, дар нашему королю от императора Керна..."},{"a":"tavern","t":"Чтобы служить советницей, но и следить за ним, верно?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...А ты, я смотрю, везде суешь свой нос."},{"a":"sia","t":"Тогда скажи мне, длинноносая Найя..."},{"a":"sia","t":"Тебе в таверне в последнее время не попадались странные личности?"},{"a":"tavern","t":"У нас тут полно странных личностей! Подвыпившие орки, лавочники..."},{"a":"tavern","t":"Но страннее всех выглядит девушка, что сидит вон там в углу."},{"a":"yami","t":"...!"},{"a":"sia","t":"Сбежала..."},{"a":"sia","t":"Азумская шпионка! ...Или убийца."},{"a":"sia","t":"Нужно все время быть на чеку..."}]},{"id":"sia_03","i":3,"title":"Незваная гостья","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Мы собрали вас здесь сегодня, чтобы отпраздновать невероятную щедрость короля."},{"a":"sia","t":"В последние месяцы он пожертвовал несколько миллионов золотых из собственной казны..."},{"a":"sia","t":"...нескольким местным храмам, школам и сиротским приютам."},{"a":"sia","t":"На этот пир приглашаются все, поэтому расскажите своим друзьям и родным."},{"a":"sia","t":"Да здравствует король Рейнгольд!"},{"a":"yami","t":"Тиран Рейнгольд, твоему правлению пришел конец!"},{"a":"king","t":"А-а-а..."},{"a":"sia","t":"Сюрикэн!.. Азумская шпионка!"},{"a":"sia","t":"Стража! Оцепить замок! Не дайте никому уйти!"},{"a":"sia","t":"Аргон, беги за убийцей!"},{"a":"argon","t":"Сию секунду!"},{"a":"sia","t":"Ах ты немытый шут! Король ранен! Ищи целителя немедленно!"},{"a":"leather","t":"Фу, как грубо."},{"a":"sia","t":"(У меня все входы были под максимальным наблюдением...)"},{"a":"sia","t":"(...Кто эта девушка?)"}]},{"id":"sia_04","i":4,"title":"Опаленные письма","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Длинноносая Найя, мне кажется, ты должна мне кое-что объяснить."},{"a":"tavern","t":"Ой, госпожа Леонель... Мне кажется, это ВЫ должны мне кое-что объяснить."},{"a":"sia","t":"Прошу прощения?"},{"a":"tavern","t":"Я перехватила несколько ОЧЕНЬ интересных писем. Отправленных вами, как я полагаю."},{"a":"tavern","t":"Может, вместе почитаем?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Давайте посмотрим... Печать Керна, адресовано лично императору Керна?"},{"a":"tavern","t":"Ну и ну! Я-то надеялась на скандальную любовную историю, но, полагаю, измена тоже сойдет."},{"a":"sia","t":"Н-найя, прошу тебя, прекрати!"},{"a":"tavern","t":"О! А вот самое пикантное!"},{"a":"tavern","t":"«Король Рейнгольд — круглый дурак, чье присутствие на троне крайне выгодно для вас»."},{"a":"tavern","t":"«Если оставить его в живых, это повредит его королевству даже больше, чем смерть правителя»."},{"a":"sia","t":"..."},{"a":"tavern","t":"Такие недобрые слова звучат как-то совсем неподобающе для его советницы!"},{"a":"sia","t":"Длинноносая... Найя... Ты за это заплатишь!"},{"a":"tavern","t":"Возможно, когда-нибудь. Но пока что заплатить придется вам. И, подозреваю, кругленькую сумму."},{"a":"sia","t":"...До шантажа решила опуститься?"},{"a":"tavern","t":"Это ведь такой маленький грех по сравнению с изменой!"},{"a":"tavern","t":"С другой стороны, если вы планировали причинить вред нашему королю..."},{"a":"sia","t":"Пф. Хорошо. Назови свою цену. И молись, чтобы моя шпионская сеть никогда не обхитрила твою, Найя."},{"a":"tavern","t":"Буду ждать с нетерпением!"}]},{"id":"sia_a","i":4,"title":"Каприз короля","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"sia","t":"Мой король."},{"a":"king","t":"Милая Сиа! Чем могу помочь?"},{"a":"sia","t":"У вас в последнее время, случайно, не было этих ваших приступов капризности?"},{"a":"king","t":"Н-нет! Нет, конечно! Никогда!"},{"a":"sia","t":"Странно. Согласно нашим гроссбухам, хранилище №36 до краев заполнено <c1>кунаями</c1>."},{"a":"sia","t":"Мне ведь не нужно напоминать его величеству, что это чрезвычайно редкий предмет."},{"a":"king","t":"У-уверен, этому есть совершенно логи..."},{"a":"sia","t":"Кроме того, многие из редчайших древностей королевства были замечены в руках у простого люда."},{"a":"sia","t":"Ваша щедрость похвальна..."},{"a":"sia","t":"...но, пожалуйста, воздержитесь от раздачи бесценных артефактов из-за перепадов настроения."},{"a":"king","t":"Пф. Хорошо! С сегодняшнего дня я становлюсь другим человеком!"},{"a":"sia","t":"Спасибо за понимание. Позвольте откланяться."},{"a":"king","t":"Моя воля сильна! Я не нуждаюсь в материальных благах!"},{"a":"king","t":"В этом помещении не помешает несколько <c1>королевских клинков</c1>, правда?"}]},{"id":"sia_05","i":5,"title":"Агент Свон","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"«...События приняли крутой поворот, когда на короля Рейнгольда было произведено покушение."},{"a":"sia","t":"Похоже, за покушением стоит Азума. Дальнейшим расследованием займется агент Свон»."},{"a":"king","t":"Сиа! Что ты делаешь?"},{"a":"sia","t":"Не обращайте внимания, просто письмо пишу."},{"a":"sia","t":"(Вернее, доклад императору Керна...)"},{"a":"king","t":"Очень хорошо! Меня ждут несколько чужеземных сановников."},{"a":"king","t":"Возможно, они немного... обижены на поход по магазинам в прошлый раз."},{"a":"king","t":"Я бы совсем не отказался от твоей помощи для разрядки обстановки!"},{"a":"sia","t":"Конечно. Буду через минуту, мой король."},{"a":"sia","t":"Если сообщить императору Керна о покушении, это может привести к ужасным последствиям..."},{"a":"sia","t":"Мне... нужно еще время подумать. Это королевство... еще не готово противостоять Керну."},{"a":"sia","t":"Ради всеобщей безопасности... полагаю, я могу опустить эту деталь..."},{"a":"sia","t":"«Все идет по плану. Агенту Свону не о чем докладывать в этом месяце»."}]},{"id":"sia_06","i":6,"title":"Роза и заноза","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"king","t":"Сиа! К тебе гость! Кстати, парень вполне царственного вида."},{"a":"sia","t":"Царственного, мой король? Это ведь не..."},{"a":"donovan","t":"Леди Сиа."},{"a":"sia","t":"Донован..."},{"a":"sia","t":"Мой король, вас ждет срочное дело в сокровищнице. Я бы порекомендовала немедленно им заняться."},{"a":"king","t":"О, уже пришла последняя партия чистого золота? Жду не дождусь!"},{"a":"donovan","t":"Что за дурак этот король, да?"},{"a":"sia","t":"Какая нелегкая принесла тебя в королевство Рейнгольда, алхимик?"},{"a":"donovan","t":"Как всегда, сразу к сути дела, агент Свон."},{"a":"donovan","t":"Я просто в отпуске по личным обстоятельствам. С разрешения императора Керна, конечно."},{"a":"donovan","t":"Нюхаю цветы, пробую зелья... Отпуск алхимика, так сказать."},{"a":"sia","t":"И изо всех мест ты выбрал это?"},{"a":"donovan","t":"Похоже, в этом отсталом королевстве немало искусных алхимиков."},{"a":"donovan","t":"Хотя если обнаружится, что преданность лебедя пошатнулась..."},{"a":"sia","t":"Ты высказался, Донован. Можешь идти и наслаждаться своим... отпуском."},{"a":"donovan","t":"Как пожелаете, леди Сиа. Было приятно пообщаться, как всегда."},{"a":"sia","t":"Очередная заноза в заднице."}]},{"id":"sia_07","i":7,"title":"Незнакомка из города золота","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Донован? Надеюсь, я не прерываю... шпионство."},{"a":"donovan","t":"О! Леди Сиа!"},{"a":"donovan","t":"Нет, совсем нет! Я просто осматриваюсь."},{"a":"sia","t":"Не стоит быть таким скрытным. В Потерянном городе золота рады видеть всех."},{"a":"sia","t":"Однако следует помнить, что любое <c1>чистое золото</c1>, найденное в нем, принадлежит королю Рейнгольду."},{"a":"sia","t":"За свой вклад храбрые путешественники получают награды."},{"a":"donovan","t":"Ясно. Весьма... щедрый правитель."},{"a":"donovan","t":"Из <c1>чистого золота</c1> затем чеканят монеты, что приводит к резкой инфляции валюты..."},{"a":"sia","t":"Верно. Я вижу, вы перехватываете мои письма к императору."},{"a":"donovan","t":"Мне нравится быть в курсе."},{"a":"sia","t":"Раз уж вы здесь, сделайте полезное дело и отнесите немного <c1>чистого золота</c1> в замок."},{"a":"donovan","t":"Конечно. Все что угодно для моей леди."},{"a":"sia","t":"Постарайтесь не сломать на обратном пути ноготь, дорогой Донован."}]},{"id":"sia_08","i":8,"title":"На перекрестке судьбы","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"tavern","t":"Мой маленький лебедь вернулся! Сама пунктуальность, как и ожидалось от нашего лучшего управленца."},{"a":"sia","t":"Я явилась на твой призыв, длинноносая Найя. У меня паршивое настроение, так что давай, пожалуйста, побыстрее."},{"a":"tavern","t":"Тогда приготовься к тому, что все станет еще паршивее! Я перехватила письмо одного алхимика..."},{"a":"tavern","t":"Экспресс-магипочта, между прочим! Ты не поверишь, как трудно такое раздобыть!"},{"a":"sia","t":"Ты же не хочешь сказать, что..."},{"a":"tavern","t":"Мне кажется, Донован пронюхал о твой маленькой игре."},{"a":"sia","t":"Если ты его перехватила, то..."},{"a":"tavern","t":"Именно так, оно никуда не денется! Если ты заплатишь, конечно."},{"a":"sia","t":"Я... Хорошо. Назови свою цену, Найя. Я заплачу."},{"a":"tavern","t":"Я повысила свои обычные расценки. За этот приз я прошу особый гонорар."},{"a":"sia","t":"Хорошо. Я..."},{"a":"tavern","t":"Выбери сторону, Сиа. Вот моя цена."},{"a":"sia","t":"..."},{"a":"tavern","t":"Сидение на двух стульях подобно опасной паутине... и, похоже, ты впечатляюще в ней запуталась."},{"a":"tavern","t":"Конечно, в зависимости от твоего ответа, я, возможно, помогу..."}]},{"id":"sia_09","i":9,"title":"Цепочка измены","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Дорогой Донован! У меня есть просьба, если вы не против."},{"a":"donovan","t":"Да? Ну что ж, послушаем."},{"a":"sia","t":"Отправляйтесь к императору. Скажите ему, что агент Свон мертв. Погиб с честью трагической смертью, верно служа империи."},{"a":"donovan","t":"П-простите?"},{"a":"sia","t":"Я ухожу, Донован. Меняю сторону, если хотите."},{"a":"sia","t":"И именно вы сообщите эту новость. И, конечно, подтвердите мою историю."},{"a":"donovan","t":"А-абсурд! Это государственная измена! Я никогда..."},{"a":"sia","t":"Я верю, что вы это сделаете, Донован. Если, конечно, не хотите, чтобы весь мир узнал рецепт вашего эликсира бессмертия?"},{"a":"donovan","t":"Продолжаете блефовать, Сиа? Я никому не рассказывал об этом рецепте. Не может быть, чтобы..."},{"a":"sia","t":"Что там входило в состав? Крылья столетней поденки?.. Вода из Стикса?.."},{"a":"donovan","t":"Э-это..."},{"a":"sia","t":"Так много ингредиентов... Не было ли там еще чуток вина для вкуса?"},{"a":"donovan","t":"М-молчать! МОЛЧАТЬ! Я не знаю, какие темные силы сообщили вам об этом..."},{"a":"sia","t":"Похоже, вы недооценили мою шпионскую сеть."},{"a":"donovan","t":"...Но я сыграю в вашу маленькую игру. На этот раз."},{"a":"sia","t":"Вечная неудачница, да? Я считаю, что мои условия более чем щедрые."},{"a":"sia","t":"Что такое одно маленькое предательство в обмен на работу всей твоей жизни?"}]},{"id":"sia_10","i":10,"title":"Посмертная помощь","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Агент Шепот. Это я."},{"a":"essence","t":"(Зевает) Так быстро?"},{"a":"sia","t":"Твои сведения были точными. Хвалю за блестящую работу."},{"a":"essence","t":"Не стоит..."},{"a":"sia","t":"Донован всегда был осторожным, но, полагаю, мало что может помешать призраку подглядывать!"},{"a":"essence","t":"Абсолютно..."},{"a":"essence","t":"Он выглядел... очень злым..."},{"a":"sia","t":"Как договаривались, твою плату я положу тебе на могилу в качестве подношения."},{"a":"sia","t":"Тут еще небольшая премия. Пожалуйста, помучай Донована еще немного."},{"a":"essence","t":"Мне платят... за то, что я работаю призраком. Это здорово."}]},{"id":"sia_11","i":11,"title":"Вольный полет лебедя","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"king","t":"Сиа! Я едва сдерживаюсь! Сколько мне еще ждать, пока я смогу явить миру свои капризы?!"},{"a":"sia","t":"Прошло всего несколько дней, ваше величество. Пожалуйста, потерпите еще немного."},{"a":"king","t":"Ох! К чему вся эта бумажная волокита?"},{"a":"sia","t":"Свидетельства о рождении и другие важные административные документы, касающиеся меня."},{"a":"sia","t":"Похоже, что по чистому совпадению большая часть документов, повествующих о моей жизни в этом королевстве, пропала."},{"a":"sia","t":"Поэтому я старательно заполняю эти формы по памяти."},{"a":"king","t":"Конечно! Негоже, чтобы моя величайшая советница не была официальной подданной моего королевства!"},{"a":"king","t":"Вот! Я спешно поставлю на них свою королевскую печать!"},{"a":"king","t":"Все готово! Ни одна деталь не ускользнула от твоего взгляда, как всегда!"},{"a":"sia","t":"Спасибо, ваша светлость. Я надеюсь служить вам еще многие десятилетия."},{"a":"king","t":"На меньшее я и не надеялся!"},{"a":"king","t":"Сиа, я вижу слезу? Неужели заполнение бумаг наполняет тебя ликующей радостью?"},{"a":"sia","t":"Э-э... нет. Скорее можно сказать, что эта бумажная работа наскучила мне до слез."},{"a":"sia","t":"А теперь, может быть, обсудим ваши капризы?"},{"a":"king","t":"Давай! Как по мне, нынешняя ситуация со щитами..."}]}]},{"id":"atlab_sokka","name":"Сокка","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Великий воин Сокка","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"atlab_aang","t":"А как насчет... этого?"},{"a":"tavern","t":"О, милый трюк!"},{"a":"atlab_sokka","t":"Пф. Он постоянно так делает!"},{"a":"argon","t":"Привет. Сокка, верно? Я Аргон!"},{"a":"atlab_sokka","t":"О, привет. Если тебе нужны волшебные трюки, это к Аангу."},{"a":"argon","t":"О нет. Я не так много знаю о магии. Или об управлении стихиями."},{"a":"argon","t":"Судя по твоему снаряжению, ты похож на грозного воина."},{"a":"atlab_sokka","t":"Г-грозного воина?"},{"a":"atlab_sokka","t":"Т-так и есть! Я Сокка, великий воин команды Аватара!"},{"a":"argon","t":"Я так и знал! Наверняка ты знаешь кучу невероятных историй!"},{"a":"atlab_sokka","t":"Еще бы! Например, во время осады Агна Кел'а..."},{"a":"atlab_sokka","t":"И вот так моя тогдашняя девушка стала луной."},{"a":"argon","t":"Л-луной?!"},{"a":"atlab_sokka","t":"Да. Но тогда флот Народа Огня..."},{"a":"atlab_sokka","t":"...и бах! Я вырубил эту гигантскую сову в библиотеке."},{"a":"argon","t":"Ого! Но разве эта сова не была могучим духом?"},{"a":"atlab_sokka","t":"Верно! Но команда Аватара всегда побеждает, когда в ней Сокка!"},{"a":"atlab_sokka","t":"Кстати говоря, где Аанг?"},{"a":"argon","t":"О, он ушел около часа назад."},{"a":"atlab_sokka","t":"Ой! Я совсем потерял счет времени. Прости, Аргон, надо бежать!"}]},{"id":"atlab_sokka_02","i":2,"title":"Великий кузнец Сокка","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"blacksmith","t":"Усердно трудишься, Сокка?"},{"a":"atlab_sokka","t":"Привет, Уоллес. Спасибо, что дал воспользоваться твоими инструментами!"},{"a":"blacksmith","t":"Нет проблем! Не ожидал я, что в своем возрасте ты такой мастер!"},{"a":"atlab_sokka","t":"Когда только ты в группе не являешься повелителем стихий, приходится приобретать всевозможные навыки."},{"a":"atlab_sokka","t":"Не каждый день мне удается использовать такие прекрасные инструменты..."},{"a":"atlab_sokka","t":"Обслуживание будет проведено в мгновение ока!"},{"a":"blacksmith","t":"Меч, который ты точишь... Где ты его взял?"},{"a":"atlab_sokka","t":"Это мой космический меч! Я сам его выковал!"},{"a":"blacksmith","t":"Из звездного металла? Неплохо, парень!"},{"a":"blacksmith","t":"Это должно быть... что-то неземное!"},{"a":"atlab_sokka","t":"А то! Другого такого меча нет!"},{"a":"polonia","t":"Эй! Простите, что прерываю, но не хочет ли кто-нибудь из вас, славных ребят, помочь мне починить корабль?"},{"a":"polonia","t":"Он сегодня совсем угрюмый. Напоролся на какие-то странные железные шары и сел на мель..."},{"a":"blacksmith","t":"Получилось разбитое корыто!"},{"a":"atlab_sokka","t":"Эй, нет проблем, я из Племени Воды! Посмотрю, что можно сделать. Извини, Уоллес, мне пора!"},{"a":"blacksmith","t":"Я пока починю остальное твое снаряжение. Удачи!"}]},{"id":"atlab_sokka_03","i":3,"title":"Великий штурман Сокка","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"atlab_sokka","t":"Вот так, хотя бы благополучно доберешься до порта."},{"a":"polonia","t":"Отличная починка. Солидная!"},{"a":"atlab_sokka","t":"Твой руль держится за счет выловленных из воды досок и кусков моей рубашки."},{"a":"atlab_sokka","t":"Что тут солидного? Обычный вариант починки для Сокки."},{"a":"polonia","t":"Йо-хо-хо! А как вышло, что сухопутник вроде тебя чинит корабли?"},{"a":"atlab_sokka","t":"Жизнь Племени Воды связана с лодками и рыбалкой. Я ходил под парусом еще до того, как научился ходить ногами."},{"a":"atlab_sokka","t":"Совсем недавно я даже разработал чертежи субмарины, работающей на энергии от управления водой!"},{"a":"polonia","t":"Это какой-то сухопутный язык. Ты это о чем?"},{"a":"atlab_sokka","t":"Это... э-э, металлический корабль, который ходит под водой."},{"a":"polonia","t":"Похоже, ты просто отправляешь морских волков на дно в шикарной коробке."},{"a":"engineer","t":"Ты сейчас сказал «крайне опасный неиспытанный прототип»?"},{"a":"atlab_sokka","t":"А... не совсем..."},{"a":"engineer","t":"Ты мне нравишься. Пойдем со мной, новенький."},{"a":"polonia","t":"Йо-хо-хо, назад в море! Поднять якоря, пока сюда не добрались охотники за наживой!"},{"a":"polonia","t":"Ар-р, на этот раз лучше увернуться от плавучих железных шаров."}]},{"id":"atlab_sokka_04","i":4,"title":"Великий изобретатель Сокка","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"engineer","t":"Замечательно! Врать не буду, чертеж у тебя немного кустарный..."},{"a":"engineer","t":"Но если чуток попахать, думаю, эта субмарина заработает!"},{"a":"atlab_sokka","t":"Гениально, правда? Я так и знал!"},{"a":"atlab_sokka","t":"Хотя нужно не забывать, что управлять ею смогут только повелители стихии воды."},{"a":"engineer","t":"Это все детали. Мы что-нибудь придумаем."},{"a":"engineer","t":"Только подумай! С нею мы сможем исследовать Затонувший храм!"},{"a":"atlab_sokka","t":"Ах да, воздуха она держит немного, поэтому заплывы лучше делать короткими."},{"a":"atlab_sokka","t":"Ты слушаешь?"},{"a":"engineer","t":"Не опирайся на этот большой железный шар."},{"a":"atlab_sokka","t":"А?.. Ого! А почему?"},{"a":"engineer","t":"Мой прототип морской бомбы. Не трогай, она взрывоопасна."},{"a":"atlab_sokka","t":"Ой..."},{"a":"atlab_sokka","t":"В любом случае, дай знать, как идет работа над прототипом."},{"a":"atlab_sokka","t":"Если все получится... мы найдем им применение в будущем."}]}]},{"id":"leather","name":"Тамас","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Эй, дружище. Думаю, защитником мне быть надоело."},{"a":"leather","t":"Это ж гораздо больше обязанностей, чем я думал, дружище. У меня на кожу едва хватает времени!"},{"a":"leather","t":"Может быть, я попробую в следующем году, дружище. До встречи в городе!"}]},{"id":"leather_01","i":1,"title":"Кожа и дерево","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"leather","t":"Спасибо за помощь, дружище."},{"a":"argon","t":"Нет проблем, Тамас! Как много кожи!"},{"a":"leather","t":"Сегодня у меня большая добыча. Смотри под ноги."},{"a":"argon","t":"Ага... тут неровно... Ой!"},{"a":"leather","t":"Ой! Ай!"},{"a":"argon","t":"Прости, Тамас! Ты в порядке?"},{"a":"leather","t":"Чуток ударился башкой, дружище. Думаю, я в норме."},{"a":"leather","t":"У меня тут промелькнула гениальная идея, дружище..."},{"a":"leather","t":"Надо идти, дружище. Это важно."},{"a":"argon","t":"Э-э, конечно! Рад был помочь!"},{"a":"argon","t":"Но что мне делать со всей этой разбросанной кожей?.."}]},{"id":"leather_02","i":2,"title":"Как предсказано в пророчестве","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"leather","t":"Так я и ударился башкой, дружище. Вот тут небольшая шишка."},{"a":"mana","t":"Тебя слушают, но помочь не могут."},{"a":"mana","t":"Божественные потоки эфира показывают, но не исцеляют."},{"a":"leather","t":"Это все равно ведь магия, да? Давай, дружище, коснись своими магическими руками."},{"a":"mana","t":"Здесь нет..."},{"a":"mana","t":"!!!"},{"a":"mana","t":"Эта... судьба... непреодолима..."},{"a":"leather","t":"Точно сработало, дружище? У меня все еще малость кружится голова."},{"a":"mana","t":"Прошу прощения. Возникло новое видение, требующее медитации."},{"a":"mana","t":"Найди Любимца Богини, чтобы излечить... раны. Нужно немедленно уйти."},{"a":"leather","t":"Ладно, дружище. Погуляю, и все пройдет. В последнее время я чувствую себя довольно сильным."}]},{"id":"leather_03","i":3,"title":"Союз защитников","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"argon","t":"Итак, в городе появился, э-э, новый защитник."},{"a":"polonia","t":"Йо-хо-хо! Надеюсь, он красавчик!"},{"a":"leather","t":"Привет, дружищи."},{"a":"polonia","t":"Ракушки мне в глотку! Ты издеваешься?"},{"a":"lilu","t":"Тамас?! Когда ты..."},{"a":"leather","t":"Решил побыть защитником, дружище. Вроде не так уж и сложно."},{"a":"argon","t":"Э-э... Тамас, а расскажи-ка, чем ты занимаешься."},{"a":"leather","t":"Колочу монстров, дружище. А еще я могу учуять кожаные вещи за много миль."},{"a":"polonia","t":"Эй! Красть всякую всячину — это МОЯ фишка! Придумай свою!"},{"a":"leather","t":"Я ничего не краду, дружище. Люди просто оставляют вещи там и сям."},{"a":"lilu","t":"Скоро здесь будет интересно!"},{"a":"polonia","t":"Ар-р, наверно, ты права..."}]},{"id":"leather_04","i":4,"title":"Невоспетый герой","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Жетоны Фортуны"},"side":false,"lines":[{"a":"sia","t":"Мой король, у меня необычный доклад."},{"a":"king","t":"Как всегда, я весь внимание! Продолжай!"},{"a":"sia","t":"Герои и караваны сообщают, что дороги стали безопаснее, чем когда-либо."},{"a":"sia","t":"Монстры носа не кажут и якобы даже боятся нападать."},{"a":"king","t":"Великолепная новость!"},{"a":"sia","t":"Однако мы не можем понять причину такого странного поведения."},{"a":"sia","t":"Не менее странным является и внезапный обвал цен на рынке кожаных товаров..."},{"a":"king","t":"Я уверен, это совпадение! Давайте пировать и праздновать в честь такой хорошей новости!"},{"a":"sia","t":"Возможно, мой король... возможно."}]}]},{"id":"malady","name":"Хворь","chapters":[{"id":"malady_01","i":1,"title":"Увековечено в камне","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Приключение завершено! Потерявшееся ребятишки! В целости и сохранности!"},{"a":"argon","t":"Руины Кроноса не предназначены для игр."},{"a":"argon","t":"Пожалуй, и мне пора отсюда выбираться!"},{"a":"malady","t":"...Надеюсь, злые гиблины отстали от меня на сегодня."},{"a":"argon","t":"Здравствуйте, мисс! Вы тоже потерялись?"},{"a":"malady","t":"Не... не подходи ближе!"},{"a":"argon","t":"А?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Если будешь долго смотреть мне в глаза, обернешься камнем! Это из-за проклятия Медузы."},{"a":"malady","t":"Хотя... кажется, ты добрый."},{"a":"malady","t":"...Прости."}]},{"id":"malady_02","i":2,"title":"Он из мрамора","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"*Хм-пф* Старейшина... Оуэн..."},{"a":"elderowen","t":"Лилу! Что ты делаешь со статуей? Куда тащишь?"},{"a":"elderowen","t":"Это статуя... Аргона?!"},{"a":"lilu","t":"Пф-ф... Пф-ф... Это и есть АРГОН!"},{"a":"elderowen","t":"Ох! Стал камнем, да?"},{"a":"lilu","t":"Похоже на то. Я нашла его в таком виде в Руинах Кроноса."},{"a":"lilu","t":"Хорошо еще, что Рудо немного помог его дотащить!"},{"a":"elderowen","t":"Вот так неприятность! Вы его спасете?"},{"a":"lilu","t":"Наверно. Но ингредиенты для этого очень редкие. Их непросто достать."},{"a":"lilu","t":"Я соберу горожан. И лавочника позову! Оставлю Аргона вам."},{"a":"elderowen","t":"Конечно! Мальчик мой, надеюсь, ты не против немного побыть садовым украшением."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Ах! Дурацкие голуби! Кыш!"}]},{"id":"malady_03","i":3,"title":"Око за око","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"...Эта разросшаяся лоза не даст заскучать. Из этого мало что осталось."},{"a":"lilu","t":"Далее у нас... Кровь медузы. Будет не просто."},{"a":"malady","t":"Гм-м..."},{"a":"lilu","t":"Ай! Чудовище!"},{"a":"malady","t":"...Ты друг того человека, да?"},{"a":"lilu","t":"Аргона? Стоп. Так это ТВОИХ рук дело?"},{"a":"lilu","t":"Так, теперь все значительно упростилось. Мне нужна капелька крови Медузы..."},{"a":"malady","t":"Нет! Пожалуйста! Я не со зла!"},{"a":"lilu","t":"Ага! А кто превратил его в камень?"},{"a":"malady","t":"...Прости. Мне стало страшно, и наши взгляды встретились."},{"a":"malady","t":"Все в голове перемешалось... Никто не был так добр ко мне."},{"a":"lilu","t":"Вот же ж!... Несладко тебе пришлось."},{"a":"malady","t":"Тебе нужна кровь... Бери."},{"a":"malady","t":"А взамен... пожалуйста, возьми меня с собой. Я хочу перед ним извиниться."},{"a":"lilu","t":"Ладно... Мне не нравится эта идея. Что ж, если я превращусь в камень, не думаю, что Донован станет нас спасать."},{"a":"lilu","t":"Я за тобой слежу. А ты, наоборот, на меня не смотри!"},{"a":"malady","t":"...Хорошо. Благодарю."}]},{"id":"malady_04","i":4,"title":"Кровь и плоть","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Готово! Зелье должно сработать. Шлеп-шлеп!"},{"a":"argon","t":"А-а-ааа! Как же приятно потянуться!"},{"a":"argon","t":"Так, а в чем дело вообще?"},{"a":"lilu","t":"Хворь превратила тебя в камень. Случайно. И хочет извиниться."},{"a":"malady","t":"П-Привет! Мне так жаль. Я не хотела..."},{"a":"argon","t":"Ну-у, беда миновала. Чувствую себя прекрасно. Мышцы разве что онемели."},{"a":"argon","t":"Ты ведь Хворь? Меня зовут Аргон. Приятно познакомиться!"},{"a":"argon","t":"О, твоя повязка слезла. Давай поправлю."},{"a":"lilu","t":"Аргон! Нет!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Аргон!.. Придется объяснить ему кое-что про медуз..."},{"a":"malady","t":"О нет! Мне жаль!"},{"a":"lilu","t":"Не стоит. Сам виноват."},{"a":"malady","t":"М-могу снова поделиться кровью."},{"a":"lilu","t":"Я не очень разбираюсь в анатомии медуз, но нам стоит подождать пару дней, пока ты восстановишься."},{"a":"lilu","t":"А пока оставайся здесь. Опасно разгуливать в одиночку почти без сил."},{"a":"lilu","t":"Хотя, учитывая твои... способности, наверно, лучше переговорить со старейшиной Оуэном."},{"a":"malady","t":"...Хорошо."}]},{"id":"malady_05","i":5,"title":"С возвращением домой!","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Старейшина Оуэн, мы вернулись!"},{"a":"elderowen","t":"Аргона спасли? Прекрасные новости!"},{"a":"lilu","t":"Ну-у... не совсем. Но..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"Х-храни нас богиня! Медуза?!"},{"a":"lilu","t":"Это Хворь. Она помогла вылечить Аргона."},{"a":"lilu","t":"Ей нужно остаться здесь на какое-то время. Восстановиться."},{"a":"elderowen","t":"Понятно. Чувствую в тебе добро Прости за такую реакцию, Хворь."},{"a":"malady","t":"Из-за проклятия... Меня все ненавидят, даже чудовища. Я уже привыкла."},{"a":"elderowen","t":"В стенах нашего города мы всегда рады приветствовать тех, кто готов служить во благо."},{"a":"malady","t":"П-правда?"},{"a":"elderowen","t":"При условии, что ты закроешь глаза чем-то. Так проблем не будет."},{"a":"elderowen","t":"Хворь... Пожалуй, здесь тебе будет лучше, чем среди себе подобных."},{"a":"malady","t":"Спасибо! Меня всегда отовсюду гнали прочь..."},{"a":"elderowen","t":"Обязательно сходи к лавочнику. Там всегда найдется работа для всех."},{"a":"lilu","t":"Точно! Можешь с нами отправляться в приключения!"},{"a":"malady","t":"Я... хорошо. Спасибо вам, Лилу и Оуэн."}]}]},{"id":"ashley","name":"Эшли","chapters":[{"id":"ashley_01","i":1,"title":"Необычный самурай","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Настоящий самурай!.. Жду не дождусь!"},{"a":"argon","t":"Леди самурай! Я Аргон! Учусь на рыца..."},{"a":"ashley","t":"Ои. Я Эшли. Как дела?"},{"a":"argon","t":"О-ои?"},{"a":"tavern","t":"Ноги со стола, пожалуйста!"},{"a":"ashley","t":"Пф. Ладно."},{"a":"ashley","t":"Ну? Что тебе нужно?"},{"a":"argon","t":"Э-э... А разве самураи обычно не более организованные?"},{"a":"ashley","t":"Что? Да, ребята дома были теми еще занудами в этом отношении."},{"a":"ashley","t":"Теперь я свободна. Просто ронин. Самурай без господина."},{"a":"argon","t":"Ясно... О, точно!"},{"a":"argon","t":"У меня же было запланировано приключение с Лилу в замке с привидениями, но..."},{"a":"argon","t":"Кое-что наметилось в тренировочном зале! Можешь подменить меня?"},{"a":"ashley","t":"Конечно. Но будешь мне должен, рыцарик."}]},{"id":"ashley_02","i":2,"title":"Вооружена и готова","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"Ты Лилу, да?"},{"a":"lilu","t":"Да, именно так! Рада знакомству!"},{"a":"ashley","t":"Ну что же, давай начнем."},{"a":"lilu","t":"П-постой! Подожди!"},{"a":"lilu","t":"Мы еще не подготовились! Зелья, пайки и..."},{"a":"ashley","t":"Да не надо нам этого всего."},{"a":"ashley","t":"Выживем или умрем. Другого не дано."},{"a":"lilu","t":"Это... Нет! Это слишком опрометчиво!"},{"a":"ashley","t":"Я иду. Сюда, да?"},{"a":"lilu","t":"Нет! Это Воющий лес..."},{"a":"argon","t":"Э-э... Удачи?"}]},{"id":"ashley_03","i":3,"title":"На краю жизни","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"Это все, на что вы, монстры, способны? НУ ЖЕ!"},{"a":"lilu","t":"Эшли! Прошу, помедленнее! Я не поспеваю с исцелением!"},{"a":"ashley","t":"Это... ПУСТЯКИ!!!"},{"a":"ashley","t":"Уф... хорошее барахло, да?"},{"a":"lilu","t":"Шутишь?! Ты чуть не погибла!"},{"a":"lilu","t":"Неудивительно, что ты потеряла руку, если так себя ведешь!"},{"a":"ashley","t":"Ои. То было другое дело."},{"a":"ashley","t":"Такую ошибку... я больше не повторю."},{"a":"lilu","t":"Пф. В этот раз обойдешься без обезболивающих."},{"a":"lilu","t":"Сама виновата. Соберись с духом."},{"a":"ashley","t":"Ха-ха... ха... я это вынесу..."},{"a":"ashley","t":"Ай! Ой-ой-ой..."}]},{"id":"ashley_a","i":4,"title":"Сплошное фамильярничанье","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Жетоны Фортуны"},"side":true,"lines":[{"a":"ashley","t":"Ои. Что это тут за крошечные монстры?"},{"a":"elven","t":"Это мои дорогие фамильяры. Добро пожаловать."},{"a":"elven","t":"Достойные защитники могут прийти и взять одного из них в качестве верного спутника."},{"a":"ashley","t":"О. Питомцы, да? Я поняла."},{"a":"ashley","t":"Хорошо. Ты, зеленый. Буду звать тебя <c1>Хитрюга</c1>. Пойдем со мной."},{"a":"ashley","t":"Ты милый, <c1>Снежок</c1>. Я понесу тебя."},{"a":"elven","t":"Э-э... Боюсь, что..."},{"a":"ashley","t":"Ух ты, какая уродливая птица!"},{"a":"ashley","t":"Буду звать тебя <c1>Воробушек</c1>. Ты тоже можешь пойти со мной."},{"a":"elven","t":"Ясно... Желаю всем хорошо провести время."}]},{"id":"ashley_04","i":5,"title":"Приключения провалено успешно","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Как вчерашнее приключение прошло? Лилу выглядела расстроенной..."},{"a":"ashley","t":"Мне удалось вернуться в целости и сохранности. К сожалению."},{"a":"argon","t":"А?! Так это же ведь хорошо!"},{"a":"king","t":"Приветствую, народ! Склоните головы перед моим великолепием!"},{"a":"ashley","t":"А! Ваше Величество! Эшли готова к выполнению задания!"},{"a":"king","t":"Прекрасный пример верного солдата! Продолжайте в том же духе!"},{"a":"ashley","t":"Так точно! Спасибо, сэр!"},{"a":"tavern","t":"Простите, Рейнгольд, ваше вино еще не прибыло."},{"a":"king","t":"Так-так-так! Вернусь к вам завтра."},{"a":"argon","t":"Что случилось?"},{"a":"ashley","t":"Оу! Как-то служила я повелителю. Сработали забытые инстинкты."},{"a":"argon","t":"Круто! Расскажи!"},{"a":"ashley","t":"Нет."}]},{"id":"ashley_05","i":6,"title":"Поворотная Сказка","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"...И вот, значит, говорю я..."},{"a":"ashley","t":"«Вооружена и готова? Можно же просто сказать «Готова»!"},{"a":"argon","t":"Ха-ха-ха!"},{"a":"argon","t":"Так Эшли... что там за лорд?.."},{"a":"ashley","t":"Аргх, ты так просто не отстанешь, да? Ладно."},{"a":"ashley","t":"У самураев есть повелители, их называют дайме. Мы служим им и защищаем ценой собственной жизни."},{"a":"argon","t":"Как почетно!"},{"a":"ashley","t":"Так вот, однажды во время обеда..."},{"a":"ashley","t":"Бум! Ниндзя пришли. Целая толпа. И все... по душу моего повелителя."},{"a":"ashley","t":"Мы бились как львы. Не впервой. Но..."},{"a":"ashley","t":"Я пропустила удар. Потеряла руку."},{"a":"ashley","t":"И... и я сбежала. Оставила его умирать."},{"a":"argon","t":"Эшли..."},{"a":"ashley","t":"Ррагх! Мне стоило умереть там!"},{"a":"ashley","t":"Найя, повтори, пожалуйста."},{"a":"tavern","t":"Эшли, с тебя уже хватит на сегодня."},{"a":"ashley","t":"Ладно. Ладно. С меня хватит."},{"a":"ashley","t":"Ну что ж. Аргон, сходи к Лилу и сообщи, что я собираюсь в опасное приключение."},{"a":"argon","t":"А? Прямо сейчас?!"},{"a":"ashley","t":"Ага. Я направляюсь... в пещеры Авроры. Лучше поспешить."}]},{"id":"ashley_06","i":7,"title":"Око за Я","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"...Девчонка-ниндзя. Подслушиваешь, значит?"},{"a":"yami","t":"...Чуть-чуть. Пойдем выйдем?"},{"a":"ashley","t":"Ха! Не в настроении для драки."},{"a":"yami","t":"Мой клан сделал это с повелителем Кусуноки. Меня изгнали... но возможно... вы примете мои извинения."},{"a":"ashley","t":"Спасибо, но не стоило. Вина не на твоих плечах. На моих."},{"a":"yami","t":"Понимаю... Даже лучше, чем можно представить."},{"a":"yami","t":"Тем не менее, тебе есть ради чего и кого жить дальше."},{"a":"yami","t":"У тебя есть друзья. Милый город. Любимые питомцы."},{"a":"yami","t":"Однако если тебе и этого мало, могу вызвать тебя на дуэль."},{"a":"ashley","t":"Избавление от страданий рукой ниндзя? Ты меня балуешь."},{"a":"ashley","t":"Спасибо, но откажусь. Хотя... может, позже."},{"a":"yami","t":"Как хочешь."}]},{"id":"ashley_07","i":8,"title":"Последний бой","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"lilu","t":"Пф-ф... Пф-ф... Эшли здесь нет..."},{"a":"lilu","t":"Она опять потерялась?.."},{"a":"lilu","t":"Так... Стоп! Меня обвели вокруг пальца?"},{"a":"ashley","t":"Я же вроде к Вулкану Пепельного озера шла..."},{"a":"ashley","t":"А и ладно, без разницы."},{"a":"ashley","t":"Таааак-с! Просыпайтесь, кретины! Эшли пришла!"},{"a":"monster_Grotto_Mob","t":"Пьяный... человек?"},{"a":"ashley","t":"Сегодня обойдемся без лекаря: лишь я и жажда смерти! Дерусь до последнего вздоха!"},{"a":"ashley","t":"Я все равно победитель. Ну, кто первый?"},{"a":"monster_Ruins_Mob","t":"Ррра! Ну же!"},{"a":"ashley","t":"Так держать!"}]},{"id":"ashley_08","i":9,"title":"Бог из Астеи","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"priest","t":"О, милостивая богиня... это же?.."},{"a":"priest","t":"Ужас! Ну и бойня!"},{"a":"monster_Grotto_Mob","t":"Хе-хе-хе."},{"a":"priest","t":"Простите, чудовища. Я лишь заберу своего компаньона."},{"a":"monster_Grotto_Mob","t":"Ни за что! Ни ЗА ЧТО! Она все испортила! Женщина-самурай мертва. Мертвее некуда."},{"a":"priest","t":"Но вот же она дышит! Нашу Эшли так просто не возьмешь."},{"a":"monster_Ruins_Mob","t":"А? Сейчас перестанет!"},{"a":"priest","t":"Ты не посмеешь!"},{"a":"monster_Grotto_Mob","t":"Хе-хе-хе! И что ты сделаешь? Вылечишь нас?"},{"a":"priest","t":"Вы не оставили мне выбора. Да простит вас богиня Астея..."},{"a":"priest","t":"Потому что я не прощу."}]},{"id":"ashley_09","i":10,"title":"Тяготы постельного режима","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"Ух..."},{"a":"priest","t":"А вот и ты. Наконец."},{"a":"ashley","t":"А? Черт... и ты тоже тут. Ты здесь? Но.. как?"},{"a":"priest","t":"Кажется, богиня тебя любит. Она меня направила."},{"a":"ashley","t":"Черт... Ладно уже, дай мне уйти с миром."},{"a":"priest","t":"Если это твое истинное желание..."},{"a":"ashley","t":"Фух... Наконец-то..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"...Почему ты меня ИСЦЕЛЯЕШЬ?"},{"a":"priest","t":"Твои слова расходятся с сердцем."},{"a":"priest","t":"Магия лечения лишь усиливает твое желание жить. Если бы ты и правда хотела умереть, моя магия не справилась бы."},{"a":"ashley","t":"Ах... вот как..."},{"a":"priest","t":"А теперь отдыхай. Тебе о многом стоит подумать."}]},{"id":"ashley_10","i":11,"title":"Время подумать","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Ты вернулся! Лилу повсюду тебя искала!"},{"a":"argon","t":"...Ты выглядишь немного потрёпанным, к тому же."},{"a":"ashley","t":"Не обращай внимания, меня подлатали. Ещё и нагоняй получил."},{"a":"argon","t":"От Фрейи? Это трудно представить."},{"a":"ashley","t":"Ага. Она сказала мне начать думать. Вот я и думаю."},{"a":"tavern","t":"Думаешь? Что-то новенькое!"},{"a":"ashley","t":"Прекрати это."},{"a":"ashley","t":"...Хотелось бы так сказать, но ты прав."},{"a":"ashley","t":"Я так долго зацикливался на прошлом, что совсем разучился думать."},{"a":"argon","t":"О чём подумать?"},{"a":"ashley","t":"Хм. Куча всего."},{"a":"ashley","t":"Я и не заметил/а, как, похоже, накопил/а множество вещей, которые мне дороги."},{"a":"ashley","t":"Город. Люди. Лавочник. И ты, рыцарь-паренёк."},{"a":"ashley","t":"Понадобилось всего лишь несколько столкновений со смертью, чтобы заметить. Похоже, я медленно соображаю, хех."},{"a":"argon","t":"Я польщён, Мисс Самурай!"},{"a":"ashley","t":"Всё ещё ронин здесь. Не ждите, что это изменится в ближайшее время."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Эпилог","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"ashley","t":"Эй, Лилу! Я собираюсь в новое приключение. Присоединишься?"},{"a":"lilu","t":"Пф! Ага! Чтобы ты опять меня послала неведомо куда?"},{"a":"lilu","t":"А сама тем временем снова нарвешься на чудовищ, и мне опять ставить тебя на ноги?"},{"a":"ashley","t":"Не, я уже осознанная женщина. Тише едешь, дальше будешь."},{"a":"lilu","t":"Гм-м... Ну как хочешь."},{"a":"lilu","t":"Погоди..."},{"a":"ashley","t":"Ха-ха-ха! Шучу-шучу."},{"a":"ashley","t":"Если ты меня прикроешь, то я с тобой!"},{"a":"lilu","t":"Отлично! Однако пообещай кое-что."},{"a":"lilu","t":"Если станет совсем тяжко, мы отступим. ТЫ отступишь."},{"a":"ashley","t":"Обещаю. Слово ронина, если оно еще чего-то стоит."},{"a":"ashley","t":"Нам есть к чему возвращаться."}]}]},{"id":"yami","name":"Ями","chapters":[{"id":"yami_01","i":1,"title":"Азумская странница","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Хи-хи-хи! Что у нас здесь?"},{"a":"yami","t":"Пф. Поди прочь, урод."},{"a":"monster_forest_Boss","t":"Плохие у тебя манеры, милочка! И одежда странная!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Ага! От тебя несет Азумой, восточным королевством людей!"},{"a":"monster_forest_Boss","t":"А сюда-то тебя чего занесло, милочка?"},{"a":"monster_forest_Boss","t":"Вооружена до зубов, скупа на слова... Наемная убийца, небось?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Хи-хи! Я так и знал! Глупые людишки вечно убивают друг друга!"},{"a":"yami","t":"...Ты прав. Я прибыла сюда, чтобы убить короля-тирана."},{"a":"monster_forest_Boss","t":"Что ты за убийца, если болтаешь всем об этом? Мне-то зачем говорить?"},{"a":"yami","t":"Потому что ты умрешь и никому не расскажешь. Прощай."},{"a":"monster_forest_Boss","t":"Ай!"},{"a":"yami","t":"...Король Рейнгольд, ты следующий."}]},{"id":"yami_02","i":2,"title":"Будь охотником или добычей","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"yami","t":"...В замке серьезная система безопасности."},{"a":"yami","t":"Пароли меняются каждый день..."},{"a":"yami","t":"Стража патрулирует без привязки к графику..."},{"a":"yami","t":"Мне нужно быть..."},{"a":"argon","t":"Привет! Да, ты, в кустах!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Тоже хочешь стать рыцарем?"},{"a":"argon","t":"Сиа скоро будет здесь! Не нужно прятаться, она очень милая!"},{"a":"yami","t":"Сиа!.."},{"a":"yami","t":"Мне нужно идти. Прощай."},{"a":"argon","t":"П-постой!"},{"a":"argon","t":"Ого! Дымовая шашка?!"},{"a":"yami","t":"...Оторвалась от этого дурака."},{"a":"yami","t":"Если Сиа здесь... моя задача усложняется."},{"a":"yami","t":"Но это нужно сделать. Я не могу потерпеть неудачу."},{"a":"yami","t":"Ради Ордена... и ради своей сестры."}]},{"id":"yami_03","i":3,"title":"Поворотная точка","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"king","t":"Уважаемые жители моего королевства! Спасибо, что пришли на мой роскошный пир!"},{"a":"king","t":"Это также прекрасная возможность для всех вас лицезреть меня, красавца! Не упустите этот шанс!"},{"a":"yami","t":"(Напыщенный тиран. Как это типично.)"},{"a":"sia","t":"Э-э, да. Спасибо за эту поучительную речь, ваше величество."},{"a":"sia","t":"Мы собрали вас здесь сегодня, чтобы отпраздновать невероятную щедрость короля."},{"a":"sia","t":"В последние месяцы он пожертвовал несколько миллионов золотых из собственной казны..."},{"a":"sia","t":"...нескольким местным храмам, школам и сиротским приютам."},{"a":"sia","t":"Участвовать в празднике приглашаются все, поэтому расскажите своим друзьям и родным."},{"a":"sia","t":"Да здравствует король Рейнгольд!"},{"a":"yami","t":"(...Тираны так не поступают.)"},{"a":"yami","t":"(...Нет, Орден не стал бы лгать. Должно быть, это какая-то уловка.)"},{"a":"yami","t":"Тиран Рейнгольд, твоему правлению пришел конец!"},{"a":"sia","t":"Сюрикэн!.. Азумская убийца!"},{"a":"yami","t":"Я промахнулась?! Это невозможно!"},{"a":"sia","t":"Стража! Блокировать все выходы! Схватить эту женщину сию секунду!"}]},{"id":"yami_04","i":4,"title":"Отражение","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"yami","t":"(Я колебалась... И потерпела неудачу.)"},{"a":"yami","t":"(Неужели Орден солгал?..)"},{"a":"yami","t":"(Это неважно. Сейчас я сама по себе.)"},{"a":"argon","t":"Наконец-то я тебя нашел!"},{"a":"yami","t":"Глупый рыцарь!"},{"a":"argon","t":"Эй! Я не драться пришел!"},{"a":"yami","t":"Я на твои уловки не попадусь, рейнгольдовский пес!"},{"a":"argon","t":"...Ты же нарочно промахнулась, да?"},{"a":"yami","t":"...!"},{"a":"argon","t":"Я видел тебя на пиру. Как мне показалось, ты пожалела о том, что бросила этот сюрикэн."},{"a":"argon","t":"Король не плохой человек, понимаешь? Иногда он ведет себя странно, но старается по максимуму!"},{"a":"argon","t":"Не знаю, кто тебе за это заплатил, но вряд ли они хорошие ребята..."},{"a":"argon","t":"Может быть, вернешься в замок и извинишься? Уверен, Рейнгольд..."},{"a":"yami","t":"...Извиниться? Что за глупость?"},{"a":"yami","t":"Мне нужно о многом подумать. Не иди за мной, если тебе твоя жизнь дорога."},{"a":"argon","t":"...Она не плохой человек, я в этом уверен."},{"a":"argon","t":"Теперь нужно доложить обо всем Сиа..."},{"a":"argon","t":"Ох и устроят мне разнос..."}]},{"id":"yami_05","i":5,"title":"При лунном свете","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Солнечный свет в кронах ив, сияние прошлых веков<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>На Эльфийской поляне мы... Ай!"},{"a":"yami","t":"Холодный укол, ощущаемый тобой, — это мое лезвие на твоей шее."},{"a":"yami","t":"У меня есть вопросы. Если ответишь честно, то, возможно, я оставлю тебя в живых."},{"a":"fabric","t":"А-а-а! Д-да! Что уго... Ой!"},{"a":"yami","t":"Тихо."},{"a":"yami","t":"Глупец, которого вы называете королем... Расскажи мне о нем."},{"a":"fabric","t":"К-король Рейнгольд? Он правитель здешних земель..."},{"a":"fabric","t":"Хотя он довольно эксцентричен, нельзя отрицать его добродетель и щедрость."},{"a":"fabric","t":"...Ему не хватает опыта, но его новая советница Сиа с лихвой это компенсирует!"},{"a":"yami","t":"Невозможно!.. От твоих слов смердит трусостью, но они звучат искренне."},{"a":"yami","t":"Этот город! В нем есть оракул?"},{"a":"fabric","t":"Ага! Да! Эльфийка Серена, там, на холме!"},{"a":"fabric","t":"Таинственная незнакомка... Могу ли я иметь честь узнать ваше им... Ой!"},{"a":"yami","t":"Несколько дней назад я бы убила тебя, не задумываясь. Не разбрасывайся удачей."},{"a":"yami","t":"Возвращайся к своей пресной жизни и забудь обо всем, что здесь произошло."},{"a":"fabric","t":"...Фух! Какая волнительная встреча!"},{"a":"fabric","t":"Дева в черном... Встретимся ли мы еще, хотелось бы мне знать..."}]},{"id":"yami_06","i":6,"title":"Разбитая пешка","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"mana","t":"...Черный ветер выдает присутствие Преследующей."},{"a":"yami","t":"...Как?!"},{"a":"mana","t":"Походка Преследующей легка как перышко, но тяжелое сердце не скрыть от третьего глаза."},{"a":"yami","t":"...Хватит шарад, оракул. Мне нужны ответы."},{"a":"yami","t":"Об Ордене... О моей семье."},{"a":"mana","t":"Торговка смертью требует наставлений. Что она предлагает взамен?"},{"a":"yami","t":"Твою жизнь."},{"a":"mana","t":"...Так тому и быть."},{"a":"mana","t":"<c1>Азумский Орден когда-то занимался устранением несправедливости...</c1>"},{"a":"mana","t":"<c1>...Защитники ордена стали рабами тех, кто платит больше всех...</c1>"},{"a":"mana","t":"<c1>...Ради невыполнимой задачи в жертву приносится пешка...</c1>"},{"a":"mana","t":"<c1>...Успех или неудача, но Орден выходит победителем.</c1>"},{"a":"yami","t":"...Невозможно."},{"a":"mana","t":"Посланник сказал свое слово."},{"a":"yami","t":"...НЕВОЗМОЖНО!"},{"a":"mana","t":"..."},{"a":"mana","t":"Тот, кто ступает в тени, со временем должен искупить вину перед светом."}]},{"id":"yami_07","i":7,"title":"Разбитая пешка","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"yami","t":"Нужно скорее собираться и идти."},{"a":"inn","t":"Привет, таинственная незнакомка."},{"a":"yami","t":"Трактирщик! Я доплатила тебе за молчание."},{"a":"inn","t":"Не беспокойся, на постоялом дворе «Изумруд» мы в чужие дела не лезем!"},{"a":"inn","t":"Однако, у нас тут несколько недоброго вида посетителей, которые, похоже, ищут тебя."},{"a":"yami","t":"(Блюстители из ордена? Так скоро?)"},{"a":"inn","t":"Они не представились. Мутные какие-то ребята. Твои друзья?"},{"a":"yami","t":"Больше нет. Скажи им, что я умерла. Такое вполне могло случиться."},{"a":"inn","t":"Покидаешь нас в спешке, да? Я думал, что так и будет, и приготовил кое-какие припасы."},{"a":"yami","t":"Спасибо, трактирщик. Но там, куда я иду, они мне не понадобятся."}]},{"id":"yami_08","i":8,"title":"Путь в один конец","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"На пик Мрачный Шпиль, говоришь?"},{"a":"wood","t":"Да, я видела похожую на ниндзя девушку, подходящую под твое описание. Похоже, она была в спешке."},{"a":"sia","t":"Превосходно. Мы наконец-то выследили убийцу."},{"a":"sia","t":"Я соберу патруль и..."},{"a":"wood","t":"Ты уверена? Не думаю, что это необходимо."},{"a":"sia","t":"Почему бы и нет, Горза?"},{"a":"wood","t":"Одиночный поход на пик Мрачный Шпиль — это самоубийство. И эта девушка не взяла с собой никаких припасов."},{"a":"wood","t":"Не может быть, чтобы она этого не знала. Даже Рудо не настолько глуп, чтобы идти туда одному."},{"a":"sia","t":"Вот как? Спасибо, Горза, я приму это к сведению."},{"a":"sia","t":"Полагаю, эта проблема решится сама собой, но..."},{"a":"sia","t":"Остается горькое послевкусие. Что ты затеяла, убийца?"}]},{"id":"yami_09","i":9,"title":"Столкновение на Мрачном Шпиле (Ями)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"argon","t":"Должно быть, это судьба. Награда даже получше, чем гарпия!"},{"a":"yami","t":"Ну же, давай. Я убью тебя на месте."},{"a":"argon","t":"Не больно-то убедительны твои слова..."},{"a":"yami","t":"Ты прав. Мне уже на все наплевать."},{"a":"yami","t":"Если ты действительно хочешь моей смерти, то оставь меня умирать здесь."},{"a":"argon","t":"Я бы никогда не оставил кого-то умирать! Я отведу тебя обратно к королю Рейнгольду!"},{"a":"argon","t":"Я знаю, он все поймет! Я понесу тебя, если понадобится!"},{"a":"yami","t":"..."},{"a":"argon","t":"Давай, опля!"},{"a":"argon","t":"Держись, ты же сплошная кожа да кости! Когда ты в последний раз ела?"},{"a":"yami","t":"..."},{"a":"argon","t":"Перекуси на обратном пути, дорога предстоит нелегкая!"}]},{"id":"yami_10","i":10,"title":"В тылу врага","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Стража! Приведите подкрепление и следите за каждым ее шагом!"},{"a":"sia","t":"Аргон, пожалуйста, подожди снаружи, пока мы поговорим с этой... непрошеной гостьей."},{"a":"argon","t":"Сию секунду!"},{"a":"sia","t":"А теперь говори, убийца."},{"a":"yami","t":"Пф, именно так. Меня наняли для убийства тирана."},{"a":"yami","t":"Или я так думала. Похоже, он всего лишь шут, не замышляющий ничего плохого."},{"a":"king","t":"Ш-шут?!"},{"a":"sia","t":"Что ваш народ имеет против нашего короля?"},{"a":"yami","t":"Мой орден поражает кого-то только во имя справедливости..."},{"a":"yami","t":"Но, похоже, это была ложь. И после моего провала на меня тоже начнется охота."},{"a":"yami","t":"Я... прошу прощения. Я приму праведное... наказание..."},{"a":"yami","t":"Ух..."},{"a":"king","t":"Она упала в обморок!"},{"a":"sia","t":"Измучилась и изголодалась..."},{"a":"sia","t":"Стража! Вызовите лучших лекарей к ее постели!"},{"a":"sia","t":"Отнеситесь к ней с уважением, подобающим королевской гостье."}]},{"id":"yami_epilogue","i":11,"title":"Эпилог","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Алмазы"},"side":false,"lines":[{"a":"sia","t":"Уф... Уф... Как же высоко... до тебя лезть..."},{"a":"yami","t":"Теперь это мой дом."},{"a":"sia","t":"Почему бы не поселиться в городе? Тебя же помиловали."},{"a":"yami","t":"Мой клан, скорее всего, считает меня мертвой. Пусть так оно и остается."},{"a":"sia","t":"Понимаю. Я прослежу, чтобы тебя регулярно снабжали припасами."},{"a":"sia","t":"Теперь что касается твоего следующего задания..."},{"a":"yami","t":"Опять головорезы из империи?"},{"a":"sia","t":"Верно. Как ты знаешь, его величество приводит в ярость множество завистников."},{"a":"sia","t":"Дополнительную информацию о своих целях найдешь в этом документе."},{"a":"yami","t":"Будет сделано."},{"a":"sia","t":"Мне тяжело это говорить, но я тебе верю."},{"a":"sia","t":"Мне пора возвращаться. Хотя перспектива спуска меня не радует..."},{"a":"yami","t":"Сиа... Рейнгольд..."},{"a":"yami","t":"Спасибо вам. От всего сердца."}]}]}];
